/**
 * Small reusable form controls for the pipeline builder properties panel.
 * Every control accepts `darkMode` and switches between dark/light classes
 * (same convention as the rest of the app).
 */

import React, { useEffect, useRef, useState } from 'react';

const inputBase =
  'w-full px-3 py-2 rounded-lg border text-sm focus:outline-none focus:ring-2 focus:ring-blue-500';

const inputColors = (darkMode: boolean) =>
  darkMode
    ? 'bg-gray-700 border-gray-600 text-white'
    : 'bg-white border-gray-300 text-gray-900';

const labelCls = (darkMode: boolean) =>
  `block text-xs font-medium mb-1 ${darkMode ? 'text-gray-400' : 'text-gray-600'}`;

const fieldCls = (darkMode: boolean, mono = false) =>
  `${inputBase} ${inputColors(darkMode)}${mono ? ' font-mono' : ''}`;

export const TextInput: React.FC<{
  label?: string;
  value: string;
  onChange: (v: string) => void;
  placeholder?: string;
  darkMode: boolean;
  mono?: boolean;
  hint?: string;
  list?: string;
}> = ({ label, value, onChange, placeholder, darkMode, mono, hint, list }) => (
  <div className="mb-3">
    {label && <label className={labelCls(darkMode)}>{label}</label>}
    <input
      type="text"
      value={value}
      placeholder={placeholder}
      list={list}
      onChange={(e) => onChange(e.target.value)}
      className={fieldCls(darkMode, mono)}
    />
    {hint && (
      <p className={`mt-1 text-xs ${darkMode ? 'text-gray-500' : 'text-gray-400'}`}>{hint}</p>
    )}
  </div>
);

export const NumberInput: React.FC<{
  label?: string;
  value: number;
  onChange: (v: number) => void;
  min?: number;
  max?: number;
  step?: number;
  darkMode: boolean;
}> = ({ label, value, onChange, min, max, step, darkMode }) => (
  <div className="mb-3">
    {label && <label className={labelCls(darkMode)}>{label}</label>}
    <input
      type="number"
      value={value}
      min={min}
      max={max}
      step={step}
      onChange={(e) => onChange(Number(e.target.value))}
      className={fieldCls(darkMode)}
    />
  </div>
);

export const SelectInput: React.FC<{
  label?: string;
  value: string;
  options: { value: string; label: string }[];
  onChange: (v: string) => void;
  darkMode: boolean;
  placeholder?: string;
}> = ({ label, value, options, onChange, darkMode, placeholder }) => {
  const opts = placeholder ? [{ value: '', label: placeholder }, ...options] : options;
  return (
    <div className="mb-3">
      {label && <label className={labelCls(darkMode)}>{label}</label>}
      <select
        value={value}
        onChange={(e) => onChange(e.target.value)}
        className={fieldCls(darkMode)}
      >
        {opts.map((o) => (
          <option key={o.value} value={o.value}>
            {o.label}
          </option>
        ))}
      </select>
    </div>
  );
};

export const TextArea: React.FC<{
  label?: string;
  value: string;
  onChange: (v: string) => void;
  rows?: number;
  darkMode: boolean;
  mono?: boolean;
  placeholder?: string;
}> = ({ label, value, onChange, rows = 3, darkMode, mono, placeholder }) => (
  <div className="mb-3">
    {label && <label className={labelCls(darkMode)}>{label}</label>}
    <textarea
      value={value}
      rows={rows}
      placeholder={placeholder}
      onChange={(e) => onChange(e.target.value)}
      className={fieldCls(darkMode, mono)}
    />
  </div>
);

export const Checkbox: React.FC<{
  label: string;
  checked: boolean;
  onChange: (v: boolean) => void;
  darkMode: boolean;
}> = ({ label, checked, onChange, darkMode }) => (
  <label
    className={`flex items-center gap-2 mb-3 cursor-pointer text-sm ${
      darkMode ? 'text-gray-300' : 'text-gray-700'
    }`}
  >
    <input
      type="checkbox"
      checked={checked}
      onChange={(e) => onChange(e.target.checked)}
      className="w-4 h-4 rounded accent-blue-500"
    />
    {label}
  </label>
);

export const JsonEditor: React.FC<{
  label?: string;
  value: Record<string, any>;
  onChange: (v: Record<string, any>) => void;
  darkMode: boolean;
}> = ({ label, value, onChange, darkMode }) => {
  const [draft, setDraft] = useState(() => JSON.stringify(value, null, 2));
  const [invalid, setInvalid] = useState(false);
  const draftRef = useRef(draft);
  draftRef.current = draft;

  // Adopt external value changes (e.g. a reloaded pipeline) without
  // clobbering the user's in-progress (possibly invalid) edits.
  useEffect(() => {
    let parsed: unknown;
    try {
      parsed = JSON.parse(draftRef.current);
    } catch {
      return;
    }
    if (JSON.stringify(parsed) === JSON.stringify(value)) return;
    setDraft(JSON.stringify(value, null, 2));
    setInvalid(false);
  }, [value]);

  const handleChange = (text: string) => {
    setDraft(text);
    try {
      const parsed = JSON.parse(text);
      setInvalid(false);
      onChange(parsed);
    } catch {
      setInvalid(true);
    }
  };

  return (
    <div className="mb-3">
      {label && <label className={labelCls(darkMode)}>{label}</label>}
      <textarea
        value={draft}
        rows={6}
        spellCheck={false}
        onChange={(e) => handleChange(e.target.value)}
        className={fieldCls(darkMode, true)}
      />
      {invalid && <p className="mt-1 text-xs text-red-500">Invalid JSON</p>}
    </div>
  );
};

export const Section: React.FC<{
  title: string;
  children: React.ReactNode;
  darkMode: boolean;
}> = ({ title, children, darkMode }) => (
  <div
    className={`p-3 mb-3 rounded-lg border ${
      darkMode ? 'border-gray-700 bg-gray-800/30' : 'border-gray-200 bg-gray-50/50'
    }`}
  >
    <h3
      className={`text-xs font-semibold uppercase tracking-wide mb-3 ${
        darkMode ? 'text-gray-400' : 'text-gray-500'
      }`}
    >
      {title}
    </h3>
    {children}
  </div>
);
