/** Default config for a freshly added step of the given kind. */
export function defaultConfig(kind: StepKind, name: string): StepConfig {
  switch (kind) {
    case 'agent':
      return { name, agent: '' };
    case 'plugin':
      return { name, plugin: '' };
    case 'endpoint':
      return { name, endpoint: '' };
    case 'ingestion':
      return { name, ingestion: '' };
    case 'transform':
      return { name, transform: '' };
    case 'parallel':
      return { name, parallel: { steps: [] } };
    case 'map':
      return { name, map: { agent: '', items: '$.input.items' } };
    case 'loop':
      return { name, loop: { step: {} } };
    case 'sub_pipeline':
      return { name, sub_pipeline: '' };
  }
}

/** Default nested children for a freshly added step. */
export function defaultChildren(kind: StepKind, baseName: string): CanvasStep[] {
  if (kind === 'parallel') {
    return [
      {
        id: `${baseName}-child-1`,
        kind: 'agent',
        name: `${baseName}_child_1`,
        config: defaultConfig('agent', `${baseName}_child_1`),
        children: [],
      },
    ];
  }
  if (kind === 'loop') {
    return [
      {
        id: `${baseName}-child-1`,
        kind: 'agent',
        name: `${baseName}_child_1`,
        config: defaultConfig('agent', `${baseName}_child_1`),
        children: [],
      },
    ];
  }
  return [];
}
