/**
 * Ordered-flow canvas for the visual pipeline builder.
 *
 * Top-level steps render left-to-right — horizontal position is
 * execution order. Container kinds (parallel / loop) render their
 * nested children inside a dashed box; map shows its items/strategy
 * instead. Reordering uses HTML5 drag & drop from the grip handle;
 * top-level and nested children track separate drag contexts so the
 * two levels never mix.
 */

import React, { useState } from 'react';
import {
  Bot,
  Puzzle,
  Globe,
  Inbox,
  Braces,
  Network,
  ListTree,
  Repeat,
  FolderTree,
  GripVertical,
  Trash2,
  X,
  Plus,
  ChevronUp,
  ChevronDown,
} from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import type { BuilderDraft, CanvasStep, StepConfig, StepKind, StepRunStatus } from './types';
import { KIND_META } from './defaults';

export interface CanvasProps {
  draft: BuilderDraft;
  selectedId: string | null;            // top-level step id selected, or null
  selectedChildPath: string[] | null;   // e.g. ['childId'] when a nested step is selected
  runStatuses: Record<string, StepRunStatus>;        // keyed by TOP-LEVEL step name
  issueCounts: Record<string, { errors: number; warnings: number }>; // keyed by step name
  onSelect: (id: string | null, childPath: string[] | null) => void;
  onReorder: (fromIndex: number, toIndex: number, containerId?: string) => void;
  onMove: (id: string, direction: -1 | 1) => void;
  onAddChild: (containerId: string) => void;
  onRemoveChild: (containerId: string, childId: string) => void;
  onDelete: (id: string) => void;
  darkMode: boolean;
}

/** Lucide icon per kind — component names mirror KIND_META.icon. */
const KIND_ICONS: Record<StepKind, LucideIcon> = {
  agent: Bot,
  plugin: Puzzle,
  endpoint: Globe,
  ingestion: Inbox,
  transform: Braces,
  parallel: Network,
  map: ListTree,
  loop: Repeat,
  sub_pipeline: FolderTree,
};

/** Kind accent color for the header icon (readable in light and dark). */
const ICON_COLORS: Record<StepKind, string> = {
  agent: 'text-blue-500',
  plugin: 'text-purple-500',
  endpoint: 'text-emerald-500',
  ingestion: 'text-teal-500',
  transform: 'text-amber-500',
  parallel: 'text-pink-500',
  map: 'text-indigo-500',
  loop: 'text-orange-500',
  sub_pipeline: 'text-cyan-500',
};

/** In-flight HTML5 drag: which step is being dragged and from where. */
interface DragState {
  id: string;
  /** Container id when the dragged step is a nested child, else null. */
  containerId: string | null;
}

function strVal(obj: Record<string, unknown>, key: string): string {
  const value: unknown = obj[key];
  return typeof value === 'string' ? value : '';
}

function mapConfig(config: StepConfig): Record<string, unknown> {
  return config.map && typeof config.map === 'object'
    ? (config.map as Record<string, unknown>)
    : {};
}

/** One-line resource summary shown under the kind badge. */
function stepSummary(step: CanvasStep): string {
  const { kind, config, children } = step;
  switch (kind) {
    case 'agent':
    case 'plugin':
    case 'endpoint':
    case 'ingestion': {
      const value: unknown = config[kind];
      return typeof value === 'string' && value.trim() ? value : '—';
    }
    case 'transform': {
      const value: unknown = config.transform;
      const text = typeof value === 'string' ? value : '';
      if (!text.trim()) return '—';
      return text.length > 40 ? `${text.slice(0, 40)}…` : text;
    }
    case 'map': {
      const agent = strVal(mapConfig(config), 'agent');
      return agent || '—';
    }
    case 'parallel':
      return `${children.length} step${children.length === 1 ? '' : 's'}`;
    case 'loop': {
      const agent = strVal(children[0]?.config ?? {}, 'agent');
      return agent || '—';
    }
    case 'sub_pipeline': {
      const value: unknown = config.sub_pipeline;
      return typeof value === 'string' && value.trim() ? value : '—';
    }
  }
}

function formatDuration(durationMs: number): string {
  if (durationMs >= 1000) return `${(durationMs / 1000).toFixed(1)}s`;
  return `${Math.round(durationMs)}ms`;
}

/** Small error/warning count pills (top-right of a card). */
const IssueBadges: React.FC<{ issues?: { errors: number; warnings: number } }> = ({ issues }) => {
  if (!issues) return null;
  return (
    <>
      {issues.errors > 0 && (
        <span
          title={`${issues.errors} error${issues.errors === 1 ? '' : 's'}`}
          className="flex h-4 min-w-[16px] items-center justify-center rounded-full bg-red-500 px-1 text-[10px] font-semibold leading-none text-white"
        >
          {issues.errors}
        </span>
      )}
      {issues.warnings > 0 && (
        <span
          title={`${issues.warnings} warning${issues.warnings === 1 ? '' : 's'}`}
          className="flex h-4 min-w-[16px] items-center justify-center rounded-full bg-amber-500 px-1 text-[10px] font-semibold leading-none text-white"
        >
          {issues.warnings}
        </span>
      )}
    </>
  );
};

/** Run-status dot + duration; nothing for `pending`. */
const StatusDot: React.FC<{ status?: StepRunStatus }> = ({ status }) => {
  if (!status || status.status === 'pending') return null;
  const dotClass =
    status.status === 'running'
      ? 'bg-blue-500 animate-pulse'
      : status.status === 'success'
        ? 'bg-green-500'
        : status.status === 'failed'
          ? 'bg-red-500'
          : 'bg-gray-400';
  return (
    <span className="flex items-center gap-1" title={status.error ?? status.status}>
      <span className={`h-2 w-2 rounded-full ${dotClass}`} />
      {status.durationMs != null && (
        <span className="text-[10px] leading-none text-gray-400 dark:text-gray-500">
          {formatDuration(status.durationMs)}
        </span>
      )}
    </span>
  );
};

interface ChildCardProps {
  child: CanvasStep;
  parentId: string;
  selected: boolean;
  issues?: { errors: number; warnings: number };
  dragState: DragState | null;
  onDragStart: () => void;
  onDragEnd: () => void;
  onDrop: () => void;
  onSelect: () => void;
  onRemove: () => void;
  darkMode: boolean;
}

/** Compact nested step card (parallel/loop children). */
const ChildCard: React.FC<ChildCardProps> = ({
  child,
  parentId,
  selected,
  issues,
  dragState,
  onDragStart,
  onDragEnd,
  onDrop,
  onSelect,
  onRemove,
  darkMode,
}) => {
  const [isDragOver, setIsDragOver] = useState(false);
  const Icon = KIND_ICONS[child.kind];

  // Only a child dragged out of this same container can be dropped here.
  const canAcceptDrop = dragState !== null && dragState.containerId === parentId;
  const showDropTarget = isDragOver && canAcceptDrop;

  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
    if (!canAcceptDrop) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    setIsDragOver(true);
  };

  const handleDragLeave = (e: React.DragEvent<HTMLDivElement>) => {
    if (!e.currentTarget.contains(e.relatedTarget as Node | null)) setIsDragOver(false);
  };

  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
    if (!canAcceptDrop) return;
    e.preventDefault();
    setIsDragOver(false);
    onDrop();
  };

  return (
    <div
      className={`group flex cursor-pointer select-none items-center gap-1.5 rounded-md border p-1.5 transition-colors ${
        darkMode ? 'border-gray-600 text-gray-100' : 'border-gray-200 text-gray-900'
      } ${
        showDropTarget
          ? 'bg-blue-50 dark:bg-blue-900/30'
          : darkMode
            ? 'bg-gray-700'
            : 'bg-white'
      } ${
        showDropTarget ? 'ring-2 ring-blue-400' : selected ? 'ring-2 ring-blue-500' : ''
      }`}
      onClick={(e) => {
        e.stopPropagation();
        onSelect();
      }}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      <span
        draggable
        onDragStart={(e) => {
          e.dataTransfer.effectAllowed = 'move';
          e.dataTransfer.setData('text/plain', child.id);
          onDragStart();
        }}
        onDragEnd={onDragEnd}
        className={`cursor-grab active:cursor-grabbing ${
          darkMode ? 'text-gray-500 hover:text-gray-300' : 'text-gray-400 hover:text-gray-600'
        }`}
        title="Drag to reorder"
      >
        <GripVertical size={14} />
      </span>
      <span className={ICON_COLORS[child.kind]}>
        <Icon size={14} />
      </span>
      <span className="min-w-0 flex-1 truncate text-xs font-medium">{child.name}</span>
      <IssueBadges issues={issues} />
      <button
        onClick={(e) => {
          e.stopPropagation();
          onRemove();
        }}
        className={`rounded p-0.5 transition-colors opacity-0 group-hover:opacity-100 focus:opacity-100 ${
          darkMode
            ? 'text-gray-400 hover:bg-gray-600 hover:text-red-400'
            : 'text-gray-400 hover:bg-gray-200 hover:text-red-600'
        }`}
        title="Remove child step"
      >
        <X size={14} />
      </button>
    </div>
  );
};

interface NodeCardProps {
  step: CanvasStep;
  selected: boolean;
  selectedChildId: string | null;
  runStatus?: StepRunStatus;
  issueCounts: Record<string, { errors: number; warnings: number }>;
  canMoveUp: boolean;
  canMoveDown: boolean;
  dragState: DragState | null;
  onDragStart: (id: string, containerId: string | null) => void;
  onDragEnd: () => void;
  onDrop: () => void;
  onDropChild: (childId: string) => void;
  onSelect: () => void;
  onSelectChild: (childId: string) => void;
  onMove: (direction: -1 | 1) => void;
  onDelete: () => void;
  onAddChild: () => void;
  onRemoveChild: (childId: string) => void;
  darkMode: boolean;
}

/** A single top-level step card (fixed width, ~240px). */
const NodeCard: React.FC<NodeCardProps> = ({
  step,
  selected,
  selectedChildId,
  runStatus,
  issueCounts,
  canMoveUp,
  canMoveDown,
  dragState,
  onDragStart,
  onDragEnd,
  onDrop,
  onDropChild,
  onSelect,
  onSelectChild,
  onMove,
  onDelete,
  onAddChild,
  onRemoveChild,
  darkMode,
}) => {
  const [isDragOver, setIsDragOver] = useState(false);
  const Icon = KIND_ICONS[step.kind];
  const meta = KIND_META[step.kind];
  const issues = issueCounts[step.name];
  const summary = stepSummary(step);

  // A top-level card only accepts top-level drags; nested children
  // handle their own drops inside the container body.
  const canAcceptDrop = dragState !== null && dragState.containerId === null;
  const showDropTarget = isDragOver && canAcceptDrop;

  const ringClass = showDropTarget
    ? 'ring-2 ring-blue-400'
    : runStatus?.status === 'running'
      ? 'ring-2 ring-blue-500'
      : runStatus?.status === 'success'
        ? 'ring-2 ring-green-500'
        : runStatus?.status === 'failed'
          ? 'ring-2 ring-red-500'
          : selected
            ? 'ring-2 ring-blue-500'
            : '';

  const backgroundClass = showDropTarget
    ? 'bg-blue-50 dark:bg-blue-900/30'
    : 'bg-gray-100 dark:bg-gray-800';

  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
    if (!canAcceptDrop) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    setIsDragOver(true);
  };

  const handleDragLeave = (e: React.DragEvent<HTMLDivElement>) => {
    if (!e.currentTarget.contains(e.relatedTarget as Node | null)) setIsDragOver(false);
  };

  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
    if (!canAcceptDrop) return;
    e.preventDefault();
    setIsDragOver(false);
    onDrop();
  };

  const buttonClass = `rounded p-0.5 transition-colors disabled:pointer-events-none disabled:opacity-30 ${
    darkMode
      ? 'text-gray-500 hover:bg-gray-700 hover:text-gray-200'
      : 'text-gray-400 hover:bg-gray-200 hover:text-gray-700'
  }`;

  return (
    <div
      className={`group w-60 shrink-0 cursor-pointer select-none rounded-lg border p-3 transition-colors ${backgroundClass} ${ringClass} ${
        darkMode ? 'border-gray-700 text-gray-100' : 'border-gray-200 text-gray-900'
      }`}
      onClick={onSelect}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      {/* Header: drag handle, icon, name, status, move/delete actions */}
      <div className="flex items-center gap-1.5">
        <span
          draggable
          onDragStart={(e) => {
            e.dataTransfer.effectAllowed = 'move';
            e.dataTransfer.setData('text/plain', step.id);
            onDragStart(step.id, null);
          }}
          onDragEnd={onDragEnd}
          className={`cursor-grab active:cursor-grabbing ${
            darkMode ? 'text-gray-500 hover:text-gray-300' : 'text-gray-400 hover:text-gray-600'
          }`}
          title="Drag to reorder"
        >
          <GripVertical size={16} />
        </span>
        <span className={ICON_COLORS[step.kind]}>
          <Icon size={16} />
        </span>
        <span className="min-w-0 flex-1 truncate text-sm font-medium">{step.name}</span>
        <IssueBadges issues={issues} />
        <StatusDot status={runStatus} />
        <button
          onClick={() => onMove(-1)}
          disabled={!canMoveUp}
          className={buttonClass}
          title="Move up"
        >
          <ChevronUp size={14} />
        </button>
        <button
          onClick={() => onMove(1)}
          disabled={!canMoveDown}
          className={buttonClass}
          title="Move down"
        >
          <ChevronDown size={14} />
        </button>
        <button
          onClick={onDelete}
          className={`${buttonClass} opacity-0 group-hover:opacity-100 focus:opacity-100`}
          title="Delete step"
        >
          <Trash2 size={14} />
        </button>
      </div>

      {/* Kind badge + summary line */}
      <div className="mt-2 flex items-center gap-1.5">
        <span className={`rounded px-1.5 py-0.5 text-[10px] font-medium ${meta.badge}`}>
          {meta.label}
        </span>
      </div>
      <p className="mt-1 truncate text-xs text-gray-500 dark:text-gray-400" title={summary}>
        {summary}
      </p>

      {/* Map: no children — show items expression and strategy */}
      {step.kind === 'map' && (
        <div
          className={`mt-2 space-y-1 rounded-lg border border-dashed p-2 text-xs ${
            darkMode ? 'border-gray-600 text-gray-400' : 'border-gray-300 text-gray-500'
          }`}
        >
          <p className="truncate">
            <span className="font-medium text-gray-400 dark:text-gray-500">items:</span>{' '}
            {strVal(mapConfig(step.config), 'items') || '—'}
          </p>
          <p className="truncate">
            <span className="font-medium text-gray-400 dark:text-gray-500">strategy:</span>{' '}
            {strVal(mapConfig(step.config), 'strategy') || '—'}
          </p>
        </div>
      )}

      {/* Parallel / loop: dashed body with nested child cards */}
      {(step.kind === 'parallel' || step.kind === 'loop') && (
        <div
          className={`mt-2 rounded-lg border-2 border-dashed p-2 ${
            darkMode ? 'border-gray-600' : 'border-gray-300'
          }`}
        >
          <p className="mb-1.5 text-[10px] font-semibold uppercase tracking-wider text-gray-400 dark:text-gray-500">
            {meta.label}
          </p>
          <div className="space-y-1.5">
            {step.children.map((child) => (
              <ChildCard
                key={child.id}
                child={child}
                parentId={step.id}
                selected={child.id === selectedChildId}
                issues={issueCounts[child.name]}
                dragState={dragState}
                onDragStart={() => onDragStart(child.id, step.id)}
                onDragEnd={onDragEnd}
                onDrop={() => onDropChild(child.id)}
                onSelect={() => onSelectChild(child.id)}
                onRemove={() => onRemoveChild(child.id)}
                darkMode={darkMode}
              />
            ))}
          </div>
          {step.kind === 'parallel' && (
            <button
              onClick={onAddChild}
              className={`mt-1.5 flex w-full items-center justify-center gap-1 rounded-md border border-dashed py-1 text-xs transition-colors ${
                darkMode
                  ? 'border-gray-600 text-gray-400 hover:bg-gray-700 hover:text-gray-200'
                  : 'border-gray-300 text-gray-500 hover:bg-gray-200 hover:text-gray-700'
              }`}
              title="Add child agent step"
            >
              <Plus size={14} />
              Add agent
            </button>
          )}
        </div>
      )}
    </div>
  );
};

export const Canvas: React.FC<CanvasProps> = ({
  draft,
  selectedId,
  selectedChildPath,
  runStatuses,
  issueCounts,
  onSelect,
  onReorder,
  onMove,
  onAddChild,
  onRemoveChild,
  onDelete,
  darkMode,
}) => {
  const [dragState, setDragState] = useState<DragState | null>(null);

  // Resolve drop indexes from the live arrays so top-level and nested
  // children are never confused (dragState carries the container id).
  const handleDrop = (targetId: string, targetContainerId: string | null) => {
    if (!dragState) return;
    if (dragState.containerId !== targetContainerId) return;
    const list =
      targetContainerId === null
        ? draft.steps
        : (draft.steps.find((s) => s.id === targetContainerId)?.children ?? []);
    const fromIndex = list.findIndex((s) => s.id === dragState.id);
    const toIndex = list.findIndex((s) => s.id === targetId);
    if (fromIndex === -1 || toIndex === -1 || fromIndex === toIndex) return;
    onReorder(fromIndex, toIndex, targetContainerId ?? undefined);
    setDragState(null);
  };

  return (
    <div className="flex-1 overflow-x-auto">
      {draft.steps.length === 0 ? (
        <div className="flex h-full items-center justify-center p-8">
          <p className={`text-sm ${darkMode ? 'text-gray-400' : 'text-gray-500'}`}>
            Add steps from the palette on the left
          </p>
        </div>
      ) : (
        <div className="flex items-start gap-3 p-4">
          {draft.steps.map((step, index) => {
            const childSelectedId =
              selectedId === step.id && selectedChildPath && selectedChildPath.length > 0
                ? selectedChildPath[0]
                : null;
            return (
              <React.Fragment key={step.id}>
                <NodeCard
                  step={step}
                  selected={selectedId === step.id && childSelectedId === null}
                  selectedChildId={childSelectedId}
                  runStatus={runStatuses[step.name]}
                  issueCounts={issueCounts}
                  canMoveUp={index > 0}
                  canMoveDown={index < draft.steps.length - 1}
                  dragState={dragState}
                  onDragStart={(id, containerId) => setDragState({ id, containerId })}
                  onDragEnd={() => setDragState(null)}
                  onDrop={() => handleDrop(step.id, null)}
                  onDropChild={(childId) => handleDrop(childId, step.id)}
                  onSelect={() => onSelect(step.id, null)}
                  onSelectChild={(childId) => onSelect(step.id, [childId])}
                  onMove={(direction) => onMove(step.id, direction)}
                  onDelete={() => onDelete(step.id)}
                  onAddChild={() => onAddChild(step.id)}
                  onRemoveChild={(childId) => onRemoveChild(step.id, childId)}
                  darkMode={darkMode}
                />
                {index < draft.steps.length - 1 && (
                  <span
                    aria-hidden
                    className={`self-center shrink-0 select-none text-xl leading-none ${
                      darkMode ? 'text-gray-600' : 'text-gray-300'
                    }`}
                  >
                    →
                  </span>
                )}
              </React.Fragment>
            );
          })}
        </div>
      )}
    </div>
  );
};
