import React, { useEffect, useState } from 'react';
import toast from 'react-hot-toast';
import { X } from 'lucide-react';

export interface YamlPanelProps {
  yaml: string; // latest generated YAML (parent re-renders on draft change)
  applyError: string | null;
  onApply: (text: string) => void;
  onClose: () => void;
  darkMode: boolean;
}

export const YamlPanel: React.FC<YamlPanelProps> = ({
  yaml,
  applyError,
  onApply,
  onClose,
  darkMode,
}) => {
  const [text, setText] = useState(yaml);

  // Sync with the latest generated YAML. The parent only regenerates the
  // YAML when the canvas changes, so this doesn't clobber user edits.
  useEffect(() => {
    setText(yaml);
  }, [yaml]);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(text);
      toast.success('Copied to clipboard');
    } catch {
      toast.error('Failed to copy');
    }
  };

  return (
    <div className="fixed inset-0 z-40">
      {/* Backdrop — click to close */}
      <div className="absolute inset-0 bg-black/30" onClick={onClose} />

      {/* Panel */}
      <div
        className={`absolute right-0 top-0 h-full w-[480px] max-w-full flex flex-col shadow-2xl ${
          darkMode ? 'bg-gray-800 border-l border-gray-700' : 'bg-white border-l border-gray-200'
        }`}
      >
        {/* Header */}
        <div
          className={`flex items-center justify-between px-4 py-3 border-b ${
            darkMode ? 'border-gray-700' : 'border-gray-200'
          }`}
        >
          <h2 className={`text-sm font-semibold ${darkMode ? 'text-white' : 'text-gray-900'}`}>
            YAML
          </h2>
          <button
            onClick={onClose}
            className={`p-1.5 rounded transition-colors ${
              darkMode ? 'hover:bg-gray-700 text-gray-400' : 'hover:bg-gray-100 text-gray-500'
            }`}
            title="Close"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Textarea */}
        <div className="flex-1 min-h-0">
          <textarea
            value={text}
            onChange={(e) => setText(e.target.value)}
            spellCheck={false}
            className={`w-full h-full p-4 font-mono text-xs resize-none focus:outline-none ${
              darkMode ? 'bg-gray-900 text-gray-200' : 'bg-gray-50 text-gray-800'
            }`}
          />
        </div>

        {/* Apply error */}
        {applyError && (
          <div
            className={`px-4 py-2 text-xs border-t ${
              darkMode
                ? 'bg-red-900/50 text-red-300 border-red-800'
                : 'bg-red-50 text-red-600 border-red-200'
            }`}
          >
            {applyError}
          </div>
        )}

        {/* Footer */}
        <div
          className={`flex items-center gap-2 px-4 py-3 border-t ${
            darkMode ? 'border-gray-700' : 'border-gray-200'
          }`}
        >
          <button
            onClick={handleCopy}
            className={`px-3 py-1.5 text-xs font-medium rounded transition-colors ${
              darkMode
                ? 'bg-gray-700 text-gray-200 hover:bg-gray-600'
                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
            }`}
          >
            Copy
          </button>
          <button
            onClick={() => onApply(text)}
            className={`px-3 py-1.5 text-xs font-medium text-white rounded transition-colors ${
              darkMode ? 'bg-blue-600 hover:bg-blue-700' : 'bg-blue-500 hover:bg-blue-600'
            }`}
          >
            Apply YAML
          </button>
        </div>
      </div>
    </div>
  );
};
