import React, { useState } from 'react';
import {
  AlertTriangle,
  CheckCircle2,
  ChevronDown,
  ChevronUp,
  Loader2,
  XCircle,
} from 'lucide-react';
import { ValidationIssue } from './types';

export interface ProblemsPanelProps {
  issues: ValidationIssue[];
  valid: boolean;
  validating: boolean;
  onSelectStep: (stepName: string) => void;
  darkMode: boolean;
}

export const ProblemsPanel: React.FC<ProblemsPanelProps> = ({
  issues,
  valid,
  validating,
  onSelectStep,
  darkMode,
}) => {
  const [open, setOpen] = useState(true);

  const errors = issues.filter((issue) => issue.severity === 'error');
  const warnings = issues.filter((issue) => issue.severity === 'warning');

  return (
    <div
      className={`border-t flex flex-col ${
        open ? 'h-40' : ''
      } ${darkMode ? 'bg-gray-800 border-gray-700' : 'bg-white border-gray-200'}`}
    >
      {/* Header */}
      <div className="flex items-center gap-3 px-4 py-2 shrink-0">
        <h3 className={`text-sm font-semibold ${darkMode ? 'text-gray-200' : 'text-gray-800'}`}>
          Problems
        </h3>
        {errors.length > 0 && (
          <span className={`text-xs font-medium ${darkMode ? 'text-red-400' : 'text-red-600'}`}>
            {errors.length} error{errors.length !== 1 ? 's' : ''}
          </span>
        )}
        {warnings.length > 0 && (
          <span className={`text-xs font-medium ${darkMode ? 'text-amber-400' : 'text-amber-600'}`}>
            {warnings.length} warning{warnings.length !== 1 ? 's' : ''}
          </span>
        )}
        {valid && issues.length === 0 && (
          <span
            className={`flex items-center gap-1 text-xs font-medium ${darkMode ? 'text-green-400' : 'text-green-600'}`}
          >
            <CheckCircle2 className="w-4 h-4" />
            Valid
          </span>
        )}
        {validating && (
          <span
            className={`flex items-center gap-1 text-xs ${darkMode ? 'text-gray-400' : 'text-gray-500'}`}
          >
            <Loader2 className="w-4 h-4 animate-spin" />
            Validating…
          </span>
        )}
        <button
          onClick={() => setOpen(!open)}
          className={`ml-auto p-1 rounded transition-colors ${
            darkMode ? 'hover:bg-gray-700 text-gray-400' : 'hover:bg-gray-100 text-gray-500'
          }`}
          title={open ? 'Collapse' : 'Expand'}
        >
          {open ? <ChevronDown className="w-4 h-4" /> : <ChevronUp className="w-4 h-4" />}
        </button>
      </div>

      {/* Body */}
      {open && (
        <div className="flex-1 overflow-y-auto px-4 pb-3">
          {issues.length === 0 ? (
            <div
              className={`flex items-center gap-2 text-sm ${darkMode ? 'text-gray-400' : 'text-gray-500'}`}
            >
              <CheckCircle2 className={`w-4 h-4 ${darkMode ? 'text-green-400' : 'text-green-600'}`} />
              No problems — pipeline is valid
            </div>
          ) : (
            [...errors, ...warnings].map((issue, index) => (
              <button
                key={`${index}-${issue.message}`}
                disabled={!issue.stepName}
                onClick={() => issue.stepName && onSelectStep(issue.stepName)}
                className={`w-full flex items-start gap-2 text-left text-sm py-1 rounded ${
                  issue.stepName ? 'cursor-pointer hover:underline' : 'cursor-default'
                } ${
                  issue.severity === 'error'
                    ? darkMode
                      ? 'text-red-400'
                      : 'text-red-600'
                    : darkMode
                      ? 'text-amber-400'
                      : 'text-amber-600'
                }`}
              >
                {issue.severity === 'error' ? (
                  <XCircle className="w-4 h-4 mt-0.5 shrink-0" />
                ) : (
                  <AlertTriangle className="w-4 h-4 mt-0.5 shrink-0" />
                )}
                {issue.stepName && (
                  <span
                    className={`shrink-0 font-mono text-[10px] px-1.5 py-0.5 rounded ${
                      darkMode ? 'bg-gray-700 text-gray-300' : 'bg-gray-200 text-gray-600'
                    }`}
                  >
                    {issue.stepName}
                  </span>
                )}
                <span>{issue.message}</span>
              </button>
            ))
          )}
        </div>
      )}
    </div>
  );
};
