import React from 'react';
import {
  fieldLabel,
  normalizeSchema,
  type JsonSchema,
} from './schemaUtils';

export interface SchemaFieldProps {
  name: string;
  schema: JsonSchema;
  rootSchema: JsonSchema;
  value: any;
  required?: boolean;
  darkMode?: boolean;
  depth?: number;
  onChange: (value: any) => void;
}

const inputClass = (darkMode: boolean) =>
  `w-full px-2 py-1.5 text-xs border rounded ${
    darkMode
      ? 'bg-gray-700 border-gray-600 text-white placeholder-gray-400'
      : 'bg-white border-gray-300 text-gray-900 placeholder-gray-500'
  }`;

const labelClass = (darkMode: boolean) =>
  `text-xs font-medium ${darkMode ? 'text-gray-300' : 'text-gray-700'}`;

/**
 * Renders a single JSON Schema property as an editable control.
 * Nested objects recurse (capped); complex arrays use a JSON textarea.
 */
export const SchemaField: React.FC<SchemaFieldProps> = ({
  name,
  schema,
  rootSchema,
  value,
  required = false,
  darkMode = false,
  depth = 0,
  onChange,
}) => {
  const prop = normalizeSchema(schema, rootSchema);
  const label = fieldLabel(name, prop);
  const description =
    typeof prop.description === 'string' ? prop.description : undefined;
  const type = prop.type || (prop.properties ? 'object' : 'string');

  const header = (
    <div className="flex items-center justify-between gap-2 mb-1">
      <label className={labelClass(darkMode)}>
        {label}
        {required && <span className="text-red-500 ml-0.5">*</span>}
        <span
          className={`ml-2 text-[10px] font-normal ${
            darkMode ? 'text-gray-500' : 'text-gray-400'
          }`}
        >
          {String(type)}
        </span>
      </label>
    </div>
  );

  const hint = description ? (
    <p className={`text-[10px] mb-1 ${darkMode ? 'text-gray-500' : 'text-gray-400'}`}>
      {description}
    </p>
  ) : null;

  if (type === 'boolean') {
    return (
      <div>
        <label className={`flex items-center gap-2 cursor-pointer ${labelClass(darkMode)}`}>
          <input
            type="checkbox"
            checked={Boolean(value)}
            onChange={(e) => onChange(e.target.checked)}
            className="rounded border-gray-300"
          />
          <span>
            {label}
            {required && <span className="text-red-500 ml-0.5">*</span>}
          </span>
        </label>
        {hint}
      </div>
    );
  }

  if (type === 'number' || type === 'integer') {
    return (
      <div>
        {header}
        {hint}
        <input
          type="number"
          step={type === 'integer' ? 1 : 'any'}
          value={value === undefined || value === null ? '' : value}
          onChange={(e) => {
            const raw = e.target.value;
            if (raw === '') {
              onChange(undefined);
              return;
            }
            const num = type === 'integer' ? parseInt(raw, 10) : parseFloat(raw);
            onChange(Number.isNaN(num) ? raw : num);
          }}
          className={inputClass(darkMode)}
          placeholder={prop.examples?.[0] != null ? String(prop.examples[0]) : label}
        />
      </div>
    );
  }

  if (type === 'array') {
    const items = normalizeSchema(prop.items || { type: 'string' }, rootSchema);
    const itemType = items.type || 'string';
    const list: any[] = Array.isArray(value) ? value : [];

    // Simple scalar arrays get row editors; everything else is JSON.
    if (itemType === 'string' || itemType === 'number' || itemType === 'integer') {
      return (
        <div>
          <div className="flex items-center justify-between mb-1">
            {header}
            <button
              type="button"
              onClick={() =>
                onChange([...list, itemType === 'string' ? '' : 0])
              }
              className={`px-2 py-0.5 text-[10px] rounded ${
                darkMode
                  ? 'bg-blue-600 hover:bg-blue-700 text-white'
                  : 'bg-blue-600 hover:bg-blue-700 text-white'
              }`}
            >
              + Add
            </button>
          </div>
          {hint}
          <div className="space-y-1">
            {list.length === 0 && (
              <p className={`text-[10px] italic ${darkMode ? 'text-gray-500' : 'text-gray-400'}`}>
                Empty array
              </p>
            )}
            {list.map((item, index) => (
              <div key={index} className="flex items-center gap-1">
                <input
                  type={itemType === 'string' ? 'text' : 'number'}
                  value={item ?? ''}
                  onChange={(e) => {
                    const next = [...list];
                    if (itemType === 'string') {
                      next[index] = e.target.value;
                    } else {
                      const n =
                        itemType === 'integer'
                          ? parseInt(e.target.value, 10)
                          : parseFloat(e.target.value);
                      next[index] = Number.isNaN(n) ? e.target.value : n;
                    }
                    onChange(next);
                  }}
                  className={inputClass(darkMode)}
                />
                <button
                  type="button"
                  onClick={() => onChange(list.filter((_, i) => i !== index))}
                  className={`px-2 py-1 text-xs rounded ${
                    darkMode
                      ? 'bg-red-700 hover:bg-red-600 text-white'
                      : 'bg-red-600 hover:bg-red-700 text-white'
                  }`}
                >
                  ×
                </button>
              </div>
            ))}
          </div>
        </div>
      );
    }

    return (
      <div>
        {header}
        {hint}
        <textarea
          value={JSON.stringify(list, null, 2)}
          onChange={(e) => {
            try {
              const parsed = JSON.parse(e.target.value);
              if (Array.isArray(parsed)) onChange(parsed);
            } catch {
              // keep typing until valid JSON
            }
          }}
          rows={4}
          className={`${inputClass(darkMode)} font-mono`}
          placeholder="[]"
        />
      </div>
    );
  }

  if (type === 'object' || prop.properties) {
    const nestedProps = prop.properties || {};
    const nestedRequired = new Set<string>(
      Array.isArray(prop.required) ? prop.required : [],
    );
    const objectValue =
      value && typeof value === 'object' && !Array.isArray(value) ? value : {};

    // Cap recursion — deep objects fall back to JSON textarea.
    if (depth >= 2 || Object.keys(nestedProps).length === 0) {
      return (
        <div>
          {header}
          {hint}
          <textarea
            value={JSON.stringify(objectValue, null, 2)}
            onChange={(e) => {
              try {
                const parsed = JSON.parse(e.target.value);
                if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
                  onChange(parsed);
                }
              } catch {
                // ignore invalid JSON while typing
              }
            }}
            rows={4}
            className={`${inputClass(darkMode)} font-mono`}
            placeholder="{}"
          />
        </div>
      );
    }

    return (
      <div
        className={`rounded border p-2 space-y-2 ${
          darkMode ? 'border-gray-600 bg-gray-800/40' : 'border-gray-200 bg-gray-50'
        }`}
      >
        {header}
        {hint}
        {Object.entries(nestedProps).map(([childName, childSchema]) => (
          <SchemaField
            key={childName}
            name={childName}
            schema={childSchema as JsonSchema}
            rootSchema={rootSchema}
            value={objectValue[childName]}
            required={nestedRequired.has(childName)}
            darkMode={darkMode}
            depth={depth + 1}
            onChange={(childValue) =>
              onChange({ ...objectValue, [childName]: childValue })
            }
          />
        ))}
      </div>
    );
  }

  // string (default) — use textarea for long / format: textarea-ish fields
  const useTextarea =
    prop.format === 'textarea' ||
    prop.maxLength > 200 ||
    ['query', 'current_query', 'message', 'prompt', 'content', 'text'].includes(
      name,
    );

  if (useTextarea) {
    return (
      <div>
        {header}
        {hint}
        <textarea
          value={value ?? ''}
          onChange={(e) => onChange(e.target.value)}
          rows={3}
          className={inputClass(darkMode)}
          placeholder={
            Array.isArray(prop.examples) && prop.examples[0] != null
              ? String(prop.examples[0])
              : `Enter ${label.toLowerCase()}...`
          }
        />
      </div>
    );
  }

  if (Array.isArray(prop.enum) && prop.enum.length > 0) {
    return (
      <div>
        {header}
        {hint}
        <select
          value={value ?? ''}
          onChange={(e) => onChange(e.target.value)}
          className={inputClass(darkMode)}
        >
          {!required && <option value="">—</option>}
          {prop.enum.map((opt: any) => (
            <option key={String(opt)} value={String(opt)}>
              {String(opt)}
            </option>
          ))}
        </select>
      </div>
    );
  }

  return (
    <div>
      {header}
      {hint}
      <input
        type="text"
        value={value ?? ''}
        onChange={(e) => onChange(e.target.value)}
        className={inputClass(darkMode)}
        placeholder={
          Array.isArray(prop.examples) && prop.examples[0] != null
            ? String(prop.examples[0])
            : `Enter ${label.toLowerCase()}...`
        }
      />
    </div>
  );
};
