/**
 * Lightweight JSON Schema helpers for Studio SchemaForm.
 * Supports $ref resolution within a single schema document and simple defaults.
 */

export type JsonSchema = Record<string, any>;

/** Resolve a local `#/$defs/...` or `#/definitions/...` $ref. */
export function resolveRef(schema: JsonSchema, root: JsonSchema): JsonSchema {
  if (!schema || typeof schema !== 'object') return {};
  if (!schema.$ref || typeof schema.$ref !== 'string') return schema;

  const ref = schema.$ref as string;
  if (!ref.startsWith('#/')) return schema;

  const parts = ref.slice(2).split('/');
  let current: any = root;
  for (const part of parts) {
    if (current == null || typeof current !== 'object') return schema;
    current = current[part];
  }
  if (!current || typeof current !== 'object') return schema;

  // Merge sibling keywords (description/title) onto the resolved target.
  const { $ref: _ignored, ...siblings } = schema;
  return { ...current, ...siblings };
}

/** Resolve $ref and pick the first non-null type from anyOf/oneOf when needed. */
export function normalizeSchema(schema: JsonSchema | undefined, root: JsonSchema): JsonSchema {
  if (!schema || typeof schema !== 'object') return {};
  let resolved = resolveRef(schema, root);

  if (!resolved.type && Array.isArray(resolved.anyOf)) {
    const picked = resolved.anyOf.find(
      (s: JsonSchema) => s && (s.type || s.$ref || s.properties),
    );
    if (picked) {
      resolved = {
        ...normalizeSchema(picked, root),
        title: resolved.title || picked.title,
        description: resolved.description || picked.description,
      };
    }
  }

  if (!resolved.type && Array.isArray(resolved.oneOf)) {
    const picked = resolved.oneOf.find(
      (s: JsonSchema) => s && (s.type || s.$ref || s.properties),
    );
    if (picked) {
      resolved = {
        ...normalizeSchema(picked, root),
        title: resolved.title || picked.title,
        description: resolved.description || picked.description,
      };
    }
  }

  // JSON Schema may express type as an array (e.g. ["string", "null"]).
  if (Array.isArray(resolved.type)) {
    const nonNull = resolved.type.find((t: string) => t !== 'null') || resolved.type[0];
    resolved = { ...resolved, type: nonNull };
  }

  return resolved;
}

/** Human-readable label from title, or prettified property name. */
export function fieldLabel(name: string, schema?: JsonSchema): string {
  if (schema?.title && typeof schema.title === 'string') return schema.title;
  return name
    .replace(/_/g, ' ')
    .replace(/([a-z])([A-Z])/g, '$1 $2')
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

/** Whether a schema looks empty / not useful for form rendering. */
export function isEmptySchema(schema: JsonSchema | undefined | null): boolean {
  if (!schema || typeof schema !== 'object') return true;
  const props = schema.properties;
  if (props && typeof props === 'object' && Object.keys(props).length > 0) {
    return false;
  }
  // Root may be a typed value without properties.
  if (schema.type && schema.type !== 'object') return false;
  return true;
}

/** Build default form values from a JSON Schema. */
export function defaultsFromSchema(
  schema: JsonSchema | undefined,
  root?: JsonSchema,
): Record<string, any> {
  if (!schema || typeof schema !== 'object') return {};
  const doc = root || schema;
  const normalized = normalizeSchema(schema, doc);

  if (normalized.default !== undefined) {
    return typeof normalized.default === 'object' && !Array.isArray(normalized.default)
      ? { ...normalized.default }
      : {};
  }

  const props = normalized.properties || {};
  const values: Record<string, any> = {};

  for (const [key, propSchema] of Object.entries(props) as [string, JsonSchema][]) {
    const prop = normalizeSchema(propSchema, doc);
    if (prop.default !== undefined) {
      values[key] = prop.default;
      continue;
    }
    switch (prop.type) {
      case 'string':
        values[key] = '';
        break;
      case 'number':
      case 'integer':
        values[key] = prop.minimum ?? 0;
        break;
      case 'boolean':
        values[key] = false;
        break;
      case 'array':
        values[key] = [];
        break;
      case 'object':
        values[key] = defaultsFromSchema(prop, doc);
        break;
      default:
        // Unknown / any — leave unset so we don't invent noise.
        break;
    }
  }

  return values;
}

/** Extract a display query string from schema form values for StudioRunRequest.query. */
export function extractQueryFromValues(values: Record<string, any>): string {
  if (!values || typeof values !== 'object') return '';

  if (typeof values.query === 'string' && values.query.trim()) return values.query;
  if (typeof values.current_query === 'string' && values.current_query.trim()) {
    return values.current_query;
  }

  for (const [key, val] of Object.entries(values)) {
    if (key.endsWith('_query') && typeof val === 'string' && val.trim()) {
      return val;
    }
  }

  for (const key of ['message', 'text', 'input', 'prompt', 'content']) {
    const val = values[key];
    if (typeof val === 'string' && val.trim()) return val;
  }

  for (const val of Object.values(values)) {
    if (typeof val === 'string' && val.trim()) return val;
  }

  try {
    const json = JSON.stringify(values);
    return json === '{}' ? '' : json;
  } catch {
    return '';
  }
}

/** Summarize schema properties for a compact read-only list. */
export function summarizeSchemaProperties(
  schema: JsonSchema | undefined,
): Array<{ name: string; type: string; required: boolean; description?: string }> {
  if (!schema || typeof schema !== 'object') return [];
  const normalized = normalizeSchema(schema, schema);
  const props = normalized.properties || {};
  const required = new Set<string>(
    Array.isArray(normalized.required) ? normalized.required : [],
  );

  return Object.entries(props).map(([name, propSchema]) => {
    const prop = normalizeSchema(propSchema as JsonSchema, schema);
    let type = prop.type || 'any';
    if (type === 'array' && prop.items) {
      const items = normalizeSchema(prop.items, schema);
      type = `array<${items.type || 'any'}>`;
    }
    return {
      name,
      type: String(type),
      required: required.has(name),
      description:
        typeof prop.description === 'string'
          ? prop.description
          : typeof prop.title === 'string'
            ? prop.title
            : undefined,
    };
  });
}
