/**
 * BuilderView — the visual pipeline builder.
 *
 * Ordered-flow canvas (left-to-right = execution order), palette of step
 * types + platform resources, per-step properties editor, instant
 * validation (client-side structural checks + debounced backend
 * validate-draft), YAML ↔ canvas sync, save/delete/load, and a run mode
 * that highlights steps by their execution status.
 */

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import toast from 'react-hot-toast';
import { useStudioStore } from '../store/useStudioStore';
import { AgentomaticClient } from '../api/client';
import { PALETTE, KIND_META } from './defaults';
import {
  addChild,
  addStep,
  draftFromPipelineDict,
  draftFromYaml,
  emptyDraft,
  issueCounts,
  mergeServerIssues,
  pipelineDictFromDraft,
  removeChild,
  removeStep,
  reorderStep,
  setMeta,
  structuralIssues,
  yamlFromDraft,
} from './serialize';
import type {
  BuilderDraft,
  BuilderResources,
  BuilderSelection,
  StepKind,
  StepRunStatus,
  ValidationIssue,
} from './types';
import { Canvas } from './Canvas';
import { PropertiesPanel } from './PropertiesPanel';
import { ProblemsPanel } from './ProblemsPanel';
import { YamlPanel } from './YamlPanel';
import { RunModal, RunResult } from './RunModal';
import {
  CheckCircleIcon,
  PlusIcon,
  TrashIcon,
  PlayIcon,
  CodeBracketIcon,
  ArrowDownTrayIcon,
} from '@heroicons/react/24/outline';

const VALIDATE_DEBOUNCE_MS = 350;

export const BuilderView: React.FC = () => {
  const { config, darkMode } = useStudioStore();

  const [draft, setDraft] = useState<BuilderDraft>(() => emptyDraft());
  const [selection, setSelection] = useState<BuilderSelection>({ type: 'pipeline' });
  const [issues, setIssues] = useState<ValidationIssue[]>([]);
  const [validating, setValidating] = useState(false);
  const [resources, setResources] = useState<BuilderResources>({
    agents: [],
    plugins: [],
    endpoints: [],
    ingestors: [],
    pipelines: [],
  });
  const [availablePipelines, setAvailablePipelines] = useState<{ name: string; description?: string }[]>([]);
  const [saving, setSaving] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [yamlOpen, setYamlOpen] = useState(false);
  const [yamlApplyError, setYamlApplyError] = useState<string | null>(null);
  const [runModalOpen, setRunModalOpen] = useState(false);
  const [running, setRunning] = useState(false);
  const [runResult, setRunResult] = useState<RunResult | null>(null);
  const [runError, setRunError] = useState<string | null>(null);
  const [runStatuses, setRunStatuses] = useState<Record<string, StepRunStatus>>({});

  const clientRef = useRef<AgentomaticClient | null>(null);
  const validateTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const validateSeq = useRef(0);

  if (!clientRef.current && config?.apiUrl) {
    clientRef.current = new AgentomaticClient(config.apiUrl, config.apiKey || undefined);
  }
  const client = clientRef.current;

  // ------------------------------------------------------------------
  // Load platform resources (palette inventory)
  // ------------------------------------------------------------------
  useEffect(() => {
    if (!client) return;
    let cancelled = false;
    (async () => {
      try {
        const [agents, plugins, endpoints, ingestors, pipelines] = await Promise.all([
          client.listAgents().catch(() => []),
          client.listPlugins().catch(() => []),
          client.listEndpoints().catch(() => []),
          client.listIngestors().catch(() => []),
          client.listPipelines().catch(() => []),
        ]);
        if (cancelled) return;
        setResources({
          agents: agents.map((a) => ({ name: a.name, description: a.description })),
          plugins: plugins.map((p) => ({ name: p.name, description: p.description })),
          endpoints: endpoints.map((e) => ({ name: e.name, description: e.description })),
          ingestors: ingestors.map((i) => ({ name: i.name, description: i.description })),
          pipelines: pipelines.map((p) => ({ name: p.name, description: p.description })),
        });
        setAvailablePipelines(pipelines.map((p) => ({ name: p.name, description: p.description })));
      } catch {
        // Resource lists are best-effort; the builder still works.
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [client]);

  // ------------------------------------------------------------------
  // Debounced validation (structural + backend validate-draft)
  // ------------------------------------------------------------------
  useEffect(() => {
    if (!client) return;
    setValidating(true);
    if (validateTimer.current) clearTimeout(validateTimer.current);
    const seq = ++validateSeq.current;
    validateTimer.current = setTimeout(async () => {
      try {
        const structural = structuralIssues(draft);
        const server = await client.validatePipelineDraft({ pipeline: pipelineDictFromDraft(draft) });
        if (seq !== validateSeq.current) return;
        setIssues(mergeServerIssues(structural, server.errors, server.warnings));
      } catch {
        if (seq !== validateSeq.current) return;
        setIssues(structuralIssues(draft));
      } finally {
        if (seq === validateSeq.current) setValidating(false);
      }
    }, VALIDATE_DEBOUNCE_MS);
    return () => {
      if (validateTimer.current) clearTimeout(validateTimer.current);
    };
  }, [draft, client]);

  const counts = useMemo(() => {
    const byStep = issueCounts(issues);
    let errors = 0;
    let warnings = 0;
    for (const issue of issues) {
      if (issue.severity === 'error') errors += 1;
      else warnings += 1;
    }
    return { byStep, errors, warnings };
  }, [issues]);

  const yaml = useMemo(() => yamlFromDraft(draft), [draft]);

  // ------------------------------------------------------------------
  // Draft mutations
  // ------------------------------------------------------------------
  const handleAddStep = useCallback(
    (kind: StepKind) => {
      setDraft((current) => {
        const next = addStep(current, kind);
        const added = next.steps[next.steps.length - 1];
        if (added) setSelection({ type: 'step', id: added.id, childPath: [] });
        return next;
      });
    },
    [],
  );

  const handleSelect = useCallback((id: string | null, childPath: string[] | null) => {
    setSelection(
      id ? { type: 'step', id, childPath: childPath ?? [] } : { type: 'pipeline' },
    );
  }, []);

  const handleIssueSelect = useCallback(
    (stepName: string) => {
      const step = draft.steps.find((s) => s.name === stepName);
      if (step) {
        setSelection({ type: 'step', id: step.id, childPath: [] });
        return;
      }
      for (const top of draft.steps) {
        const child = top.children.find((c) => c.name === stepName);
        if (child) {
          setSelection({ type: 'step', id: top.id, childPath: [child.id] });
          return;
        }
      }
    },
    [draft.steps],
  );

  // ------------------------------------------------------------------
  // Save / delete / load / run
  // ------------------------------------------------------------------
  const handleSave = useCallback(async () => {
    if (!client) return;
    setSaving(true);
    try {
      const dict = pipelineDictFromDraft(draft);
      const response = await client.savePipeline(draft.meta.name, { pipeline: dict });
      if (response.valid) {
        toast.success(`Saved pipeline '${response.name}'`);
        setAvailablePipelines((prev) => {
          const exists = prev.some((p) => p.name === response.name);
          return exists ? prev : [...prev, { name: response.name }];
        });
      } else {
        const message = response.errors.join(' · ') || 'Pipeline validation failed';
        toast.error(message);
      }
    } catch (err: any) {
      let message = err?.message || 'Failed to save pipeline';
      try {
        const detail = JSON.parse(err?.body || '{}')?.detail;
        if (detail?.message) message = detail.message;
        if (Array.isArray(detail?.errors) && detail.errors.length > 0) {
          message = `${detail.message}: ${detail.errors.join(' · ')}`;
        }
      } catch {
        // fall through to generic message
      }
      toast.error(message);
    } finally {
      setSaving(false);
    }
  }, [client, draft]);

  const handleDelete = useCallback(async () => {
    if (!client) return;
    const name = draft.meta.name;
    if (!window.confirm(`Delete pipeline '${name}'? This removes its YAML file.`)) return;
    setDeleting(true);
    try {
      await client.deletePipeline(name);
      toast.success(`Deleted pipeline '${name}'`);
      setDraft(emptyDraft());
      setSelection({ type: 'pipeline' });
      setRunStatuses({});
      setAvailablePipelines((prev) => prev.filter((p) => p.name !== name));
    } catch (err: any) {
      let message = err?.message || 'Failed to delete pipeline';
      try {
        const detail = JSON.parse(err?.body || '{}')?.detail;
        if (typeof detail === 'string') message = detail;
        else if (detail?.message) message = detail.message;
      } catch {
        // fall through
      }
      toast.error(message);
    } finally {
      setDeleting(false);
    }
  }, [client, draft.meta.name]);

  const handleLoad = useCallback(
    async (name: string) => {
      if (!client) return;
      try {
        const raw = await client.getPipelineConfig(name);
        setDraft(draftFromPipelineDict(raw));
        setSelection({ type: 'pipeline' });
        setRunStatuses({});
        setRunResult(null);
        setRunError(null);
        toast.success(`Loaded pipeline '${name}'`);
      } catch (err: any) {
        toast.error(err?.message || `Failed to load pipeline '${name}'`);
      }
    },
    [client],
  );

  const handleNew = useCallback(() => {
    setDraft(emptyDraft());
    setSelection({ type: 'pipeline' });
    setRunStatuses({});
    setRunResult(null);
    setRunError(null);
  }, []);

  const handleRun = useCallback(
    async (input: any) => {
      if (!client) return;
      setRunning(true);
      setRunError(null);
      setRunResult(null);
      setRunStatuses({});
      try {
        const response = await client.runPipeline(draft.meta.name, { input });
        const statuses: Record<string, StepRunStatus> = {};
        for (const [stepName, step] of Object.entries(response.steps)) {
          statuses[stepName] = {
            status: step.status,
            durationMs: step.duration_ms,
            error: step.error,
          };
        }
        setRunStatuses(statuses);
        setRunResult({
          status: response.status,
          output: response.output,
          steps: statuses,
          durationMs: response.duration_ms,
          error: response.error,
        });
        if (response.status === 'success') {
          toast.success(`Pipeline run completed in ${response.duration_ms.toFixed(1)}ms`);
        } else {
          toast.error(response.error || `Pipeline run finished with status '${response.status}'`);
        }
      } catch (err: any) {
        let message = err?.message || 'Failed to run pipeline';
        try {
          const detail = JSON.parse(err?.body || '{}')?.detail;
          if (typeof detail === 'string') message = detail;
          else if (detail?.message) message = detail.message;
          else if (Array.isArray(detail?.errors) && detail.errors.length > 0) {
            message = detail.errors.join(' · ');
          }
        } catch {
          // fall through
        }
        setRunError(message);
        toast.error(message);
      } finally {
        setRunning(false);
      }
    },
    [client, draft.meta.name],
  );

  const handleApplyYaml = useCallback((text: string) => {
    try {
      const next = draftFromYaml(text);
      setDraft(next);
      setSelection({ type: 'pipeline' });
      setYamlApplyError(null);
      toast.success('YAML applied — canvas updated');
    } catch (err: any) {
      setYamlApplyError(err?.message || 'Invalid YAML');
    }
  }, []);

  // ------------------------------------------------------------------
  // Palette resource lists
  // ------------------------------------------------------------------
  const resourceSections: { title: string; items: { name: string }[]; color: string }[] = [
    { title: 'Agents', items: resources.agents, color: 'blue' },
    { title: 'Plugins', items: resources.plugins, color: 'purple' },
    { title: 'Endpoints', items: resources.endpoints, color: 'emerald' },
    { title: 'Ingestors', items: resources.ingestors, color: 'teal' },
    { title: 'Sub-pipelines', items: resources.pipelines, color: 'cyan' },
  ];

  const panelCls = darkMode ? 'bg-gray-800 text-white' : 'bg-white text-gray-900';
  const borderCls = darkMode ? 'border-gray-700' : 'border-gray-200';
  const mutedCls = darkMode ? 'text-gray-400' : 'text-gray-500';

  return (
    <div className={`flex flex-col h-full ${darkMode ? 'bg-gray-900 text-white' : 'bg-gray-50 text-gray-900'}`}>
      {/* ============================= Toolbar ============================= */}
      <div className={`flex items-center gap-3 px-4 h-14 border-b ${borderCls} ${panelCls} flex-shrink-0`}>
        <input
          value={draft.meta.name}
          onChange={(e) => setDraft(setMeta(draft, { ...draft.meta, name: e.target.value }))}
          placeholder="pipeline_name"
          className={`px-3 py-1.5 rounded-lg border text-sm font-medium w-52 focus:outline-none focus:ring-2 focus:ring-blue-500 ${
            darkMode ? 'bg-gray-700 border-gray-600 text-white' : 'bg-white border-gray-300 text-gray-900'
          }`}
          title="Pipeline name"
        />

        <button
          onClick={handleNew}
          className={`flex items-center px-3 py-1.5 rounded-lg text-sm font-medium transition-colors ${
            darkMode ? 'hover:bg-gray-700 text-gray-200' : 'hover:bg-gray-100 text-gray-700'
          }`}
          title="New pipeline"
        >
          <PlusIcon className="w-4 h-4 mr-1.5" />
          New
        </button>

        <select
          value=""
          onChange={(e) => e.target.value && handleLoad(e.target.value)}
          className={`px-3 py-1.5 rounded-lg border text-sm focus:outline-none ${
            darkMode ? 'bg-gray-700 border-gray-600 text-white' : 'bg-white border-gray-300 text-gray-900'
          }`}
          title="Load existing pipeline"
        >
          <option value="" disabled>
            {availablePipelines.length > 0 ? 'Load…' : 'No saved pipelines'}
          </option>
          {availablePipelines.map((p) => (
            <option key={p.name} value={p.name}>
              {p.name}
            </option>
          ))}
        </select>

        <div className="flex-1" />

        <div className={`flex items-center text-xs font-medium px-3 py-1.5 rounded-full ${
          counts.errors > 0
            ? darkMode ? 'bg-red-900 text-red-200' : 'bg-red-100 text-red-700'
            : counts.warnings > 0
              ? darkMode ? 'bg-amber-900 text-amber-200' : 'bg-amber-100 text-amber-700'
              : darkMode ? 'bg-green-900 text-green-200' : 'bg-green-100 text-green-700'
        }`}>
          {validating ? (
            <span>Validating…</span>
          ) : counts.errors > 0 ? (
            <span>{counts.errors} error{counts.errors !== 1 ? 's' : ''}</span>
          ) : counts.warnings > 0 ? (
            <span>{counts.warnings} warning{counts.warnings !== 1 ? 's' : ''}</span>
          ) : (
            <span className="flex items-center">
              <CheckCircleIcon className="w-4 h-4 mr-1" /> Valid
            </span>
          )}
        </div>

        <button
          onClick={() => setYamlOpen(true)}
          className={`flex items-center px-3 py-1.5 rounded-lg text-sm font-medium ${
            darkMode
              ? 'bg-gray-700 text-gray-200 hover:bg-gray-600'
              : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
          }`}
          title="YAML view"
        >
          <CodeBracketIcon className="w-4 h-4 mr-1.5" />
          YAML
        </button>

        <button
          onClick={handleSave}
          disabled={saving || counts.errors > 0}
          className={`flex items-center px-4 py-1.5 rounded-lg text-sm font-medium text-white transition-colors ${
            saving || counts.errors > 0
              ? 'bg-gray-400 cursor-not-allowed'
              : 'bg-blue-600 hover:bg-blue-700'
          }`}
          title={counts.errors > 0 ? 'Fix validation errors before saving' : 'Save pipeline'}
        >
          <ArrowDownTrayIcon className="w-4 h-4 mr-1.5" />
          {saving ? 'Saving…' : 'Save'}
        </button>

        <button
          onClick={() => setRunModalOpen(true)}
          disabled={counts.errors > 0}
          className={`flex items-center px-4 py-1.5 rounded-lg text-sm font-medium text-white transition-colors ${
            counts.errors > 0 ? 'bg-gray-400 cursor-not-allowed' : 'bg-green-600 hover:bg-green-700'
          }`}
          title={counts.errors > 0 ? 'Fix validation errors before running' : 'Run with test input'}
        >
          <PlayIcon className="w-4 h-4 mr-1.5" />
          Run
        </button>

        <button
          onClick={handleDelete}
          disabled={deleting}
          className={`flex items-center px-3 py-1.5 rounded-lg text-sm font-medium transition-colors ${
            darkMode
              ? 'text-red-300 hover:bg-red-900/40'
              : 'text-red-600 hover:bg-red-50'
          }`}
          title="Delete pipeline"
        >
          <TrashIcon className="w-4 h-4 mr-1.5" />
          {deleting ? '…' : 'Delete'}
        </button>
      </div>

      {/* ========================= Main 3-pane layout ========================= */}
      <div className="flex flex-1 min-h-0 overflow-hidden">
        {/* Palette */}
        <div className={`w-56 flex-shrink-0 overflow-y-auto border-r ${borderCls} ${panelCls} p-3`}>
          <h3 className={`text-xs font-semibold uppercase tracking-wider mb-2 ${mutedCls}`}>
            Step types
          </h3>
          <div className="space-y-1.5 mb-4">
            {PALETTE.map((item) => {
              const meta = KIND_META[item.kind];
              return (
                <button
                  key={item.kind}
                  onClick={() => handleAddStep(item.kind)}
                  className={`w-full text-left px-3 py-2 rounded-lg border transition-colors ${
                    darkMode
                      ? 'hover:bg-gray-700 border-gray-700'
                      : 'hover:bg-gray-50 border-gray-200'
                  }`}
                  title={item.description}
                >
                  <div className="flex items-center">
                    <span className={`text-[10px] font-semibold px-1.5 py-0.5 rounded ${meta.badge}`}>
                      {meta.label}
                    </span>
                    <PlusIcon className={`w-3.5 h-3.5 ml-auto ${mutedCls}`} />
                  </div>
                </button>
              );
            })}
          </div>

          {resourceSections.map((section) => (
            <div key={section.title} className="mb-3">
              <h3 className={`text-xs font-semibold uppercase tracking-wider mb-1.5 ${mutedCls}`}>
                {section.title} ({section.items.length})
              </h3>
              {section.items.length === 0 ? (
                <p className={`text-xs italic ${mutedCls}`}>none</p>
              ) : (
                <div className="flex flex-wrap gap-1">
                  {section.items.map((item) => (
                    <span
                      key={item.name}
                      className={`text-xs px-1.5 py-0.5 rounded ${
                        darkMode ? 'bg-gray-700 text-gray-300' : 'bg-gray-100 text-gray-600'
                      }`}
                    >
                      {item.name}
                    </span>
                  ))}
                </div>
              )}
            </div>
          ))}
        </div>

        {/* Canvas */}
        <div className="flex-1 min-w-0 overflow-auto p-4">
          <Canvas
            draft={draft}
            selectedId={selection.type === 'step' ? selection.id : null}
            selectedChildPath={selection.type === 'step' ? selection.childPath : null}
            runStatuses={runStatuses}
            issueCounts={counts.byStep}
            onSelect={handleSelect}
            onReorder={(from, to, containerId) => setDraft((d) => reorderStep(d, from, to, containerId))}
            onMove={(id, direction) => {
              setDraft((d) => {
                const index = d.steps.findIndex((s) => s.id === id);
                if (index === -1) return d;
                return reorderStep(d, index, index + direction);
              });
            }}
            onAddChild={(containerId) => setDraft((d) => addChild(d, containerId))}
            onRemoveChild={(containerId, childId) => setDraft((d) => removeChild(d, containerId, childId))}
            onDelete={(id) => setDraft((d) => removeStep(d, id))}
            darkMode={darkMode}
          />
        </div>

        {/* Properties */}
        <div className={`w-96 flex-shrink-0 overflow-y-auto border-l ${borderCls} ${panelCls}`}>
          <PropertiesPanel
            draft={draft}
            selection={selection}
            resources={resources}
            onChange={setDraft}
            darkMode={darkMode}
          />
        </div>
      </div>

      {/* ========================= Problems bar ========================= */}
      <div className="flex-shrink-0 border-t border-gray-200 dark:border-gray-700">
        <ProblemsPanel
          issues={issues}
          valid={counts.errors === 0}
          validating={validating}
          onSelectStep={handleIssueSelect}
          darkMode={darkMode}
        />
      </div>

      {/* ========================= Overlays ========================= */}
      {yamlOpen && (
        <YamlPanel
          yaml={yaml}
          applyError={yamlApplyError}
          onApply={handleApplyYaml}
          onClose={() => setYamlOpen(false)}
          darkMode={darkMode}
        />
      )}

      <RunModal
        open={runModalOpen}
        pipelineName={draft.meta.name}
        running={running}
        result={runResult}
        error={runError}
        onClose={() => setRunModalOpen(false)}
        onRun={handleRun}
        darkMode={darkMode}
      />
    </div>
  );
};
