/**
 * Properties panel for the pipeline builder: pipeline-level settings plus
 * per-kind step editors. All edits go through the immutable serialize.ts
 * helpers so the canvas stays the single source of truth.
 */

import React from 'react';

import { KIND_META } from './defaults';
import {
  Checkbox,
  JsonEditor,
  NumberInput,
  Section,
  SelectInput,
  TextArea,
  TextInput,
} from './FieldControls';
import { MappingEditor } from './MappingEditor';
import { normMapping, renameStep, setMeta, setStepConfig } from './serialize';
import type {
  BuilderDraft,
  BuilderResources,
  BuilderSelection,
  CanvasStep,
  PipelineMeta,
} from './types';

export interface PropertiesPanelProps {
  draft: BuilderDraft;
  selection: BuilderSelection;
  resources: BuilderResources;
  /** Parent passes immutable updates (use the serialize.ts helpers). */
  onChange: (next: BuilderDraft) => void;
  darkMode: boolean;
}

const str = (v: any): string => (typeof v === 'string' ? v : v == null ? '' : String(v));
const num = (v: any): number => (typeof v === 'number' ? v : 0);
const obj = (v: any): Record<string, any> =>
  v && typeof v === 'object' && !Array.isArray(v) ? v : {};

const ON_ERROR_STEP = [
  { value: 'fail', label: 'fail' },
  { value: 'skip', label: 'skip' },
  { value: 'retry', label: 'retry' },
  { value: 'fallback', label: 'fallback' },
];

const ON_ERROR_PIPELINE: { value: PipelineMeta['on_error']; label: string }[] = [
  { value: 'fail_fast', label: 'fail_fast' },
  { value: 'continue', label: 'continue' },
  { value: 'rollback', label: 'rollback' },
];

const STRATEGY_OPTS = [
  { value: 'all', label: 'all' },
  { value: 'first', label: 'first' },
  { value: 'majority', label: 'majority' },
];

const BACKOFF_OPTS = [
  { value: 'fixed', label: 'fixed' },
  { value: 'linear', label: 'linear' },
  { value: 'exponential', label: 'exponential' },
];

const OUTPUT_SUGGESTIONS = ['$', '$.response', '$.output', '$.result', '$.text'];

export const PropertiesPanel: React.FC<PropertiesPanelProps> = ({
  draft,
  selection,
  resources,
  onChange,
  darkMode,
}) => {
  if (selection.type === 'pipeline') {
    const meta = draft.meta;
    const patchMeta = (patch: Partial<PipelineMeta>) =>
      onChange(setMeta(draft, { ...meta, ...patch }));
    return (
      <div className="p-4">
        <Section title="Pipeline settings" darkMode={darkMode}>
          <TextInput
            label="Name"
            value={meta.name}
            onChange={(v) => patchMeta({ name: v })}
            darkMode={darkMode}
          />
          <TextArea
            label="Description"
            value={meta.description}
            onChange={(v) => patchMeta({ description: v })}
            darkMode={darkMode}
          />
          <TextInput
            label="Version"
            value={meta.version}
            onChange={(v) => patchMeta({ version: v })}
            darkMode={darkMode}
          />
          <SelectInput
            label="On error"
            value={meta.on_error}
            options={ON_ERROR_PIPELINE}
            onChange={(v) => patchMeta({ on_error: v as PipelineMeta['on_error'] })}
            darkMode={darkMode}
          />
          <NumberInput
            label="Timeout (s)"
            value={meta.timeout}
            onChange={(v) => patchMeta({ timeout: v })}
            darkMode={darkMode}
          />
          <Checkbox
            label="Strict schema"
            checked={meta.strict_schema}
            onChange={(v) => patchMeta({ strict_schema: v })}
            darkMode={darkMode}
          />
          <JsonEditor
            label="Input schema"
            value={obj(meta.input_schema)}
            onChange={(v) => patchMeta({ input_schema: v })}
            darkMode={darkMode}
          />
          <JsonEditor
            label="Output schema"
            value={obj(meta.output_schema)}
            onChange={(v) => patchMeta({ output_schema: v })}
            darkMode={darkMode}
          />
          <JsonEditor
            label="Defaults"
            value={obj(meta.defaults)}
            onChange={(v) => patchMeta({ defaults: v })}
            darkMode={darkMode}
          />
          <JsonEditor
            label="Metadata"
            value={obj(meta.metadata)}
            onChange={(v) => patchMeta({ metadata: v })}
            darkMode={darkMode}
          />
        </Section>
      </div>
    );
  }

  const step = draft.steps.find((s) => s.id === selection.id);
  if (!step) {
    return (
      <div className="p-4">
        <p className={`text-sm ${darkMode ? 'text-gray-400' : 'text-gray-500'}`}>
          Select a step or pipeline settings
        </p>
      </div>
    );
  }

  let current: CanvasStep = step;
  if (selection.childPath.length > 0) {
    const child = step.children.find((c) => c.id === selection.childPath[0]);
    if (child) current = child;
  }

  const patchConfig = (next: Record<string, any>) =>
    onChange(setStepConfig(draft, selection.id, selection.childPath, next));
  const config = { ...current.config };
  const kind = current.kind;
  const isChild = selection.childPath.length > 0;
  const kindLabel = KIND_META[kind].label;

  const agentOptions = resources.agents.map((a) => ({ value: a.name, label: a.name }));
  const pluginOptions = resources.plugins.map((p) => ({ value: p.name, label: p.name }));
  const endpointOptions = resources.endpoints.map((e) => ({ value: e.name, label: e.name }));
  const ingestorOptions = resources.ingestors.map((i) => ({ value: i.name, label: i.name }));
  const pipelineOptions = resources.pipelines.map((p) => ({ value: p.name, label: p.name }));

  const inputSuggestions = [
    '$.steps.*',
    ...Object.keys(obj(draft.meta.input_schema)).map((f) => `$.input.${f}`),
    '$.defaults.',
    '$.context.',
    '$.current.',
    ...draft.steps.map((s) => `$.steps.${s.name}`),
  ];

  const hint = (text: string) => (
    <p className={`text-xs mb-3 ${darkMode ? 'text-gray-500' : 'text-gray-400'}`}>{text}</p>
  );

  const resourceField = (
    fieldLabel: string,
    value: string,
    opts: { value: string; label: string }[],
    onSelect: (v: string) => void,
    emptyHint: string,
  ) =>
    opts.length === 0 ? (
      hint(emptyHint)
    ) : (
      <SelectInput
        label={fieldLabel}
        value={value}
        options={opts}
        onChange={onSelect}
        darkMode={darkMode}
      />
    );

  const executionFields = (withCondition: boolean, withRollback: boolean) => (
    <Section title="Execution" darkMode={darkMode}>
      {withCondition && (
        <TextInput
          label="Condition"
          value={str(config.condition)}
          placeholder="e.g. $.input.ok == true"
          onChange={(v) => patchConfig({ ...config, condition: v })}
          darkMode={darkMode}
        />
      )}
      <SelectInput
        label="On error"
        value={str(config.on_error) || 'fail'}
        options={ON_ERROR_STEP}
        onChange={(v) => patchConfig({ ...config, on_error: v })}
        darkMode={darkMode}
      />
      <NumberInput
        label="Timeout (s)"
        value={num(config.timeout)}
        onChange={(v) => patchConfig({ ...config, timeout: v })}
        darkMode={darkMode}
      />
      {withRollback && (
        <TextArea
          label="Rollback"
          value={str(config.rollback)}
          rows={3}
          mono
          onChange={(v) => patchConfig({ ...config, rollback: v })}
          darkMode={darkMode}
        />
      )}
    </Section>
  );

  const retryFields = (
    retry: Record<string, any>,
    onRetry: (next: Record<string, any>) => void,
  ) => (
    <Section title="Retry" darkMode={darkMode}>
      <NumberInput
        label="Max attempts"
        value={num(retry.max_attempts) || 3}
        min={1}
        max={10}
        onChange={(v) => onRetry({ ...retry, max_attempts: v })}
        darkMode={darkMode}
      />
      <SelectInput
        label="Backoff"
        value={str(retry.backoff) || 'fixed'}
        options={BACKOFF_OPTS}
        onChange={(v) => onRetry({ ...retry, backoff: v })}
        darkMode={darkMode}
      />
      <NumberInput
        label="Base delay (s)"
        value={num(retry.base_delay) || 0.5}
        min={0.1}
        max={60}
        step={0.1}
        onChange={(v) => onRetry({ ...retry, base_delay: v })}
        darkMode={darkMode}
      />
    </Section>
  );

  const mappingsSection = (
    input: Record<string, any>,
    output: Record<string, any>,
    onInput: (v: Record<string, any>) => void,
    onOutput: (v: Record<string, any>) => void,
  ) => (
    <Section title="Mappings" darkMode={darkMode}>
      <MappingEditor
        label="input"
        mappings={input}
        suggestions={inputSuggestions}
        onChange={onInput}
        darkMode={darkMode}
      />
      <MappingEditor
        label="output"
        mappings={output}
        suggestions={OUTPUT_SUGGESTIONS}
        onChange={onOutput}
        darkMode={darkMode}
      />
    </Section>
  );

  const metadataSection = () => (
    <Section title="Metadata" darkMode={darkMode}>
      <JsonEditor
        label="Metadata"
        value={obj(config.metadata)}
        onChange={(v) => patchConfig({ ...config, metadata: v })}
        darkMode={darkMode}
      />
    </Section>
  );

  const nameField = (
    <TextInput
      label="Name"
      value={current.name}
      onChange={(v) => onChange(renameStep(draft, selection.id, selection.childPath, v))}
      darkMode={darkMode}
    />
  );

  let body: React.ReactNode;

  if (isChild) {
    body = (
      <>
        <Section title={kindLabel} darkMode={darkMode}>
          {resourceField(
            'Agent',
            str(config.agent),
            agentOptions,
            (v) => patchConfig({ ...config, agent: v }),
            'No agents registered',
          )}
        </Section>
        {mappingsSection(
          normMapping(config.input),
          normMapping(config.output),
          (v) => patchConfig({ ...config, input: v }),
          (v) => patchConfig({ ...config, output: v }),
        )}
        {retryFields(obj(config.retry), (next) => patchConfig({ ...config, retry: next }))}
        {executionFields(true, true)}
      </>
    );
  } else {
    switch (kind) {
      case 'agent':
        body = (
          <>
            <Section title={kindLabel} darkMode={darkMode}>
              {resourceField(
                'Agent',
                str(config.agent),
                agentOptions,
                (v) => patchConfig({ ...config, agent: v }),
                'No agents registered',
              )}
              <SelectInput
                label="Fallback agent"
                value={str(config.fallback_agent)}
                options={agentOptions}
                placeholder="None"
                onChange={(v) => patchConfig({ ...config, fallback_agent: v })}
                darkMode={darkMode}
              />
            </Section>
            {executionFields(true, true)}
            {retryFields(obj(config.retry), (next) => patchConfig({ ...config, retry: next }))}
            {mappingsSection(
              normMapping(config.input),
              normMapping(config.output),
              (v) => patchConfig({ ...config, input: v }),
              (v) => patchConfig({ ...config, output: v }),
            )}
            {metadataSection()}
          </>
        );
        break;
      case 'plugin':
        body = (
          <>
            <Section title={kindLabel} darkMode={darkMode}>
              {resourceField(
                'Plugin',
                str(config.plugin),
                pluginOptions,
                (v) => patchConfig({ ...config, plugin: v }),
                'No plugins registered',
              )}
            </Section>
            {executionFields(true, true)}
            {mappingsSection(
              normMapping(config.input),
              normMapping(config.output),
              (v) => patchConfig({ ...config, input: v }),
              (v) => patchConfig({ ...config, output: v }),
            )}
            {metadataSection()}
          </>
        );
        break;
      case 'endpoint':
        body = (
          <>
            <Section title={kindLabel} darkMode={darkMode}>
              {resourceField(
                'Endpoint',
                str(config.endpoint),
                endpointOptions,
                (v) => patchConfig({ ...config, endpoint: v }),
                'No endpoints registered',
              )}
              <TextInput
                label="Upstreams"
                value={Array.isArray(config.upstreams) ? config.upstreams.join(', ') : ''}
                placeholder="svc-a, svc-b"
                mono
                onChange={(v) =>
                  patchConfig({
                    ...config,
                    upstreams: v
                      .split(',')
                      .map((s) => s.trim())
                      .filter(Boolean),
                  })
                }
                darkMode={darkMode}
              />
            </Section>
            {executionFields(true, true)}
            {mappingsSection(
              normMapping(config.input),
              normMapping(config.output),
              (v) => patchConfig({ ...config, input: v }),
              (v) => patchConfig({ ...config, output: v }),
            )}
            {metadataSection()}
          </>
        );
        break;
      case 'ingestion':
        body = (
          <>
            <Section title={kindLabel} darkMode={darkMode}>
              {resourceField(
                'Ingestor',
                str(config.ingestion),
                ingestorOptions,
                (v) => patchConfig({ ...config, ingestion: v }),
                'No ingestors registered',
              )}
            </Section>
            {executionFields(true, true)}
            {mappingsSection(
              normMapping(config.input),
              normMapping(config.output),
              (v) => patchConfig({ ...config, input: v }),
              (v) => patchConfig({ ...config, output: v }),
            )}
            {metadataSection()}
          </>
        );
        break;
      case 'sub_pipeline':
        body = (
          <>
            <Section title={kindLabel} darkMode={darkMode}>
              {resourceField(
                'Pipeline',
                str(config.sub_pipeline),
                pipelineOptions,
                (v) => patchConfig({ ...config, sub_pipeline: v }),
                'No pipelines registered',
              )}
            </Section>
            {executionFields(true, true)}
            {mappingsSection(
              normMapping(config.input),
              normMapping(config.output),
              (v) => patchConfig({ ...config, input: v }),
              (v) => patchConfig({ ...config, output: v }),
            )}
            {metadataSection()}
          </>
        );
        break;
      case 'transform':
        body = (
          <>
            <Section title={kindLabel} darkMode={darkMode}>
              <TextArea
                label="Code"
                value={str(config.transform)}
                rows={10}
                mono
                placeholder="def transform(ctx):&#10;    return ctx.input"
                onChange={(v) => patchConfig({ ...config, transform: v })}
                darkMode={darkMode}
              />
            </Section>
            {executionFields(true, false)}
          </>
        );
        break;
      case 'parallel': {
        const parallelCfg = obj(config.parallel);
        const patchParallel = (next: Record<string, any>) =>
          patchConfig({ ...config, parallel: next });
        body = (
          <>
            <Section title={kindLabel} darkMode={darkMode}>
              {hint('Children are edited on the canvas.')}
              <SelectInput
                label="Strategy"
                value={str(parallelCfg.strategy) || 'all'}
                options={STRATEGY_OPTS}
                onChange={(v) => patchParallel({ ...parallelCfg, strategy: v })}
                darkMode={darkMode}
              />
              <NumberInput
                label="Max concurrency"
                value={num(parallelCfg.max_concurrency) || 5}
                min={1}
                max={20}
                onChange={(v) => patchParallel({ ...parallelCfg, max_concurrency: v })}
                darkMode={darkMode}
              />
            </Section>
            {executionFields(false, false)}
          </>
        );
        break;
      }
      case 'map': {
        const mapCfg = obj(config.map);
        const patchMap = (next: Record<string, any>) => patchConfig({ ...config, map: next });
        body = (
          <>
            <Section title={kindLabel} darkMode={darkMode}>
              {resourceField(
                'Agent',
                str(mapCfg.agent),
                agentOptions,
                (v) => patchMap({ ...mapCfg, agent: v }),
                'No agents registered',
              )}
              <TextInput
                label="Items"
                value={str(mapCfg.items)}
                placeholder="$.input.items"
                mono
                onChange={(v) => patchMap({ ...mapCfg, items: v })}
                darkMode={darkMode}
              />
              <TextInput
                label="Item key"
                value={str(mapCfg.item_key)}
                onChange={(v) => patchMap({ ...mapCfg, item_key: v })}
                darkMode={darkMode}
              />
              <TextInput
                label="Index key"
                value={str(mapCfg.index_key)}
                onChange={(v) => patchMap({ ...mapCfg, index_key: v })}
                darkMode={darkMode}
              />
              <NumberInput
                label="Max concurrency"
                value={num(mapCfg.max_concurrency) || 4}
                min={1}
                max={64}
                onChange={(v) => patchMap({ ...mapCfg, max_concurrency: v })}
                darkMode={darkMode}
              />
              <SelectInput
                label="Strategy"
                value={str(mapCfg.strategy) || 'all'}
                options={STRATEGY_OPTS}
                onChange={(v) => patchMap({ ...mapCfg, strategy: v })}
                darkMode={darkMode}
              />
              <NumberInput
                label="Item timeout (s)"
                value={num(mapCfg.item_timeout) || 60}
                onChange={(v) => patchMap({ ...mapCfg, item_timeout: v })}
                darkMode={darkMode}
              />
              <SelectInput
                label="Fallback agent"
                value={str(mapCfg.fallback_agent)}
                options={agentOptions}
                placeholder="None"
                onChange={(v) => patchMap({ ...mapCfg, fallback_agent: v })}
                darkMode={darkMode}
              />
            </Section>
            {mappingsSection(
              normMapping(mapCfg.input),
              normMapping(mapCfg.output),
              (v) => patchMap({ ...mapCfg, input: v }),
              (v) => patchMap({ ...mapCfg, output: v }),
            )}
            {executionFields(true, true)}
          </>
        );
        break;
      }
      case 'loop': {
        const loopCfg = obj(config.loop);
        const patchLoop = (next: Record<string, any>) => patchConfig({ ...config, loop: next });
        body = (
          <>
            <Section title={kindLabel} darkMode={darkMode}>
              <NumberInput
                label="Max iterations"
                value={num(loopCfg.max_iterations) || 10}
                min={1}
                max={100}
                onChange={(v) => patchLoop({ ...loopCfg, max_iterations: v })}
                darkMode={darkMode}
              />
              <TextInput
                label="Until"
                value={str(loopCfg.until)}
                placeholder="e.g. $.result.done == true"
                mono
                onChange={(v) => patchLoop({ ...loopCfg, until: v })}
                darkMode={darkMode}
              />
            </Section>
            {executionFields(false, false)}
          </>
        );
        break;
      }
      default:
        body = null;
    }
  }

  return (
    <div className="p-4">
      {nameField}
      {body}
    </div>
  );
};
