import React, { useState } from 'react';
import { AlertTriangle, CheckCircle2, Loader2, X, XCircle } from 'lucide-react';
import { StepRunStatus } from './types';

export interface RunResult {
  status: string;
  output: any;
  steps: Record<string, StepRunStatus>;
  durationMs: number;
  error: string | null;
}

export interface RunModalProps {
  open: boolean;
  pipelineName: string;
  running: boolean;
  result: RunResult | null;
  error: string | null;
  onClose: () => void;
  onRun: (input: any) => void;
  darkMode: boolean;
}

const StepStatusBadge: React.FC<{ status: string; darkMode: boolean }> = ({ status, darkMode }) => {
  switch (status) {
    case 'success':
      return (
        <span
          className={`inline-flex items-center gap-1 text-xs font-medium ${
            darkMode ? 'text-green-400' : 'text-green-600'
          }`}
        >
          <CheckCircle2 className="w-3.5 h-3.5" />
          Success
        </span>
      );
    case 'failed':
      return (
        <span
          className={`inline-flex items-center gap-1 text-xs font-medium ${
            darkMode ? 'text-red-400' : 'text-red-600'
          }`}
        >
          <XCircle className="w-3.5 h-3.5" />
          Failed
        </span>
      );
    case 'running':
      return (
        <span
          className={`inline-flex items-center gap-1 text-xs font-medium ${
            darkMode ? 'text-blue-400' : 'text-blue-600'
          }`}
        >
          <Loader2 className="w-3.5 h-3.5 animate-spin" />
          Running
        </span>
      );
    case 'skipped':
      return (
        <span className={`text-xs font-medium ${darkMode ? 'text-gray-400' : 'text-gray-500'}`}>
          Skipped
        </span>
      );
    default: // pending
      return (
        <span className={`text-xs font-medium ${darkMode ? 'text-gray-400' : 'text-gray-500'}`}>
          Pending
        </span>
      );
  }
};

export const RunModal: React.FC<RunModalProps> = ({
  open,
  pipelineName,
  running,
  result,
  error,
  onClose,
  onRun,
  darkMode,
}) => {
  const [inputText, setInputText] = useState('{}');
  const [inputError, setInputError] = useState<string | null>(null);

  if (!open) {
    return null;
  }

  const handleRun = () => {
    try {
      const parsed = JSON.parse(inputText);
      setInputError(null);
      onRun(parsed);
    } catch {
      setInputError('Invalid JSON — please check the test input.');
    }
  };

  const resultBadge = (() => {
    switch (result?.status) {
      case 'success':
        return (
          <span
            className={`inline-flex items-center gap-1 text-xs font-medium ${
              darkMode ? 'text-green-400' : 'text-green-600'
            }`}
          >
            <CheckCircle2 className="w-4 h-4" />
            Success
          </span>
        );
      case 'failed':
        return (
          <span
            className={`inline-flex items-center gap-1 text-xs font-medium ${
              darkMode ? 'text-red-400' : 'text-red-600'
            }`}
          >
            <XCircle className="w-4 h-4" />
            Failed
          </span>
        );
      case 'partial':
        return (
          <span
            className={`inline-flex items-center gap-1 text-xs font-medium ${
              darkMode ? 'text-amber-400' : 'text-amber-600'
            }`}
          >
            <AlertTriangle className="w-4 h-4" />
            Partial
          </span>
        );
      case 'running':
        return (
          <span
            className={`inline-flex items-center gap-1 text-xs font-medium ${
              darkMode ? 'text-blue-400' : 'text-blue-600'
            }`}
          >
            <Loader2 className="w-4 h-4 animate-spin" />
            Running
          </span>
        );
      default:
        return null;
    }
  })();

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/50" onClick={onClose} />

      {/* Panel */}
      <div
        className={`relative max-w-2xl w-full max-h-[85vh] flex flex-col rounded-xl shadow-2xl ${
          darkMode ? 'bg-gray-800 border border-gray-700' : 'bg-white border border-gray-200'
        }`}
      >
        {/* Header */}
        <div
          className={`flex items-center justify-between px-4 py-3 border-b shrink-0 ${
            darkMode ? 'border-gray-700' : 'border-gray-200'
          }`}
        >
          <h2 className={`text-sm font-semibold ${darkMode ? 'text-white' : 'text-gray-900'}`}>
            Run pipeline{' '}
            <span className={`font-mono text-xs ${darkMode ? 'text-gray-400' : 'text-gray-500'}`}>
              {pipelineName}
            </span>
          </h2>
          <button
            onClick={onClose}
            className={`p-1.5 rounded transition-colors ${
              darkMode ? 'hover:bg-gray-700 text-gray-400' : 'hover:bg-gray-100 text-gray-500'
            }`}
            title="Close"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Body */}
        <div className="flex-1 overflow-y-auto px-4 py-4 space-y-4">
          {/* Test input */}
          <div className="space-y-1.5">
            <label
              className={`block text-xs font-medium ${darkMode ? 'text-gray-300' : 'text-gray-600'}`}
            >
              Test input
            </label>
            <textarea
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              spellCheck={false}
              rows={4}
              className={`w-full p-3 font-mono text-xs resize-y rounded-lg border focus:outline-none ${
                darkMode
                  ? 'bg-gray-900 text-gray-200 border-gray-600 focus:border-blue-500'
                  : 'bg-gray-50 text-gray-800 border-gray-300 focus:border-blue-500'
              }`}
            />
            {inputError && (
              <p className={`text-xs ${darkMode ? 'text-red-400' : 'text-red-600'}`}>
                {inputError}
              </p>
            )}
          </div>

          {/* Run button */}
          <button
            onClick={handleRun}
            disabled={running}
            className={`flex items-center gap-2 px-4 py-2 text-xs font-medium text-white rounded-lg transition-colors disabled:opacity-50 ${
              darkMode ? 'bg-blue-600 hover:bg-blue-700' : 'bg-blue-500 hover:bg-blue-600'
            }`}
          >
            {running && <Loader2 className="w-4 h-4 animate-spin" />}
            {running ? 'Running…' : 'Run'}
          </button>

          {/* Error box */}
          {error && (
            <div
              className={`px-3 py-2 text-xs rounded-lg ${
                darkMode ? 'bg-red-900/50 text-red-300' : 'bg-red-50 text-red-600'
              }`}
            >
              {error}
            </div>
          )}

          {/* Result */}
          {result && (
            <div className="space-y-3">
              <div className="flex items-center gap-3">
                {resultBadge}
                <span
                  className={`text-xs ${darkMode ? 'text-gray-400' : 'text-gray-500'}`}
                >
                  Duration: {result.durationMs} ms
                </span>
              </div>

              {result.error && (
                <div
                  className={`px-3 py-2 text-xs rounded-lg ${
                    darkMode ? 'bg-red-900/50 text-red-300' : 'bg-red-50 text-red-600'
                  }`}
                >
                  {result.error}
                </div>
              )}

              <div className="space-y-1.5">
                <label
                  className={`block text-xs font-medium ${darkMode ? 'text-gray-300' : 'text-gray-600'}`}
                >
                  Output
                </label>
                <pre
                  className={`p-3 font-mono text-xs whitespace-pre-wrap break-all rounded-lg border overflow-auto max-h-64 ${
                    darkMode
                      ? 'bg-gray-900 text-gray-200 border-gray-600'
                      : 'bg-gray-50 text-gray-800 border-gray-300'
                  }`}
                >
                  {JSON.stringify(result.output, null, 2)}
                </pre>
              </div>

              <div className="space-y-1.5">
                <label
                  className={`block text-xs font-medium ${darkMode ? 'text-gray-300' : 'text-gray-600'}`}
                >
                  Steps
                </label>
                <table
                  className={`w-full text-xs border rounded-lg ${
                    darkMode ? 'border-gray-600' : 'border-gray-300'
                  }`}
                >
                  <thead>
                    <tr
                      className={`text-left ${darkMode ? 'bg-gray-900 text-gray-400' : 'bg-gray-100 text-gray-500'}`}
                    >
                      <th className="px-3 py-2 font-medium">Step</th>
                      <th className="px-3 py-2 font-medium">Status</th>
                      <th className="px-3 py-2 font-medium">Duration</th>
                      <th className="px-3 py-2 font-medium">Error</th>
                    </tr>
                  </thead>
                  <tbody>
                    {Object.entries(result.steps).map(([name, step]) => (
                      <tr
                        key={name}
                        className={`border-t ${
                          darkMode
                            ? 'border-gray-700 text-gray-300'
                            : 'border-gray-200 text-gray-700'
                        }`}
                      >
                        <td className="px-3 py-2 font-mono">{name}</td>
                        <td className="px-3 py-2">
                          <StepStatusBadge status={step.status} darkMode={darkMode} />
                        </td>
                        <td className="px-3 py-2">
                          {step.durationMs !== undefined ? `${step.durationMs} ms` : '—'}
                        </td>
                        <td
                          className={`px-3 py-2 ${darkMode ? 'text-red-400' : 'text-red-600'}`}
                        >
                          {step.error ?? ''}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};
