import React, { useEffect, useMemo, useState } from 'react';
import { SchemaField } from './SchemaField';
import {
  defaultsFromSchema,
  isEmptySchema,
  normalizeSchema,
  type JsonSchema,
} from './schemaUtils';

export interface SchemaFormProps {
  /** JSON Schema for the agent input (or any object schema). */
  schema?: JsonSchema | null;
  /** Controlled value. When omitted, the form manages its own state. */
  value?: Record<string, any>;
  /** Called whenever the constructed object changes. */
  onChange?: (value: Record<string, any>) => void;
  /** Optional submit handler (e.g. Run). */
  onSubmit?: (value: Record<string, any>) => void;
  darkMode?: boolean;
  /** Show Form / Raw JSON toggle (default true). */
  showViewToggle?: boolean;
  /** Disable all inputs. */
  disabled?: boolean;
  /** Optional submit button label; omit to hide the button. */
  submitLabel?: string;
  className?: string;
}

const FALLBACK_SCHEMA: JsonSchema = {
  type: 'object',
  title: 'Agent Input',
  properties: {
    query: {
      type: 'string',
      title: 'Query',
      description: 'User query or input text for the agent',
    },
  },
  required: ['query'],
};

/**
 * Schema-driven input form with Form / Raw JSON views.
 * Falls back to a simple `{ query }` field when the schema is empty.
 */
export const SchemaForm: React.FC<SchemaFormProps> = ({
  schema,
  value,
  onChange,
  onSubmit,
  darkMode = false,
  showViewToggle = true,
  disabled = false,
  submitLabel,
  className = '',
}) => {
  const effectiveSchema = useMemo(() => {
    if (isEmptySchema(schema || undefined)) return FALLBACK_SCHEMA;
    return normalizeSchema(schema as JsonSchema, schema as JsonSchema);
  }, [schema]);

  const initialDefaults = useMemo(
    () => defaultsFromSchema(effectiveSchema, effectiveSchema),
    [effectiveSchema],
  );

  const [internalValue, setInternalValue] = useState<Record<string, any>>(
    () => value ?? initialDefaults,
  );
  const [viewMode, setViewMode] = useState<'form' | 'raw'>('form');
  const [rawText, setRawText] = useState('');
  const [rawError, setRawError] = useState<string | null>(null);

  const formValue = value !== undefined ? value : internalValue;

  // Reset when schema identity changes (new agent / new schema shape).
  useEffect(() => {
    if (value === undefined) {
      setInternalValue(initialDefaults);
    }
    setRawText(JSON.stringify(value ?? initialDefaults, null, 2));
    setRawError(null);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [effectiveSchema]);

  // Keep raw text in sync when controlled value changes externally.
  useEffect(() => {
    if (viewMode === 'raw') return;
    setRawText(JSON.stringify(formValue, null, 2));
  }, [formValue, viewMode]);

  const emitChange = (next: Record<string, any>) => {
    if (value === undefined) setInternalValue(next);
    onChange?.(next);
  };

  const properties = effectiveSchema.properties || {};
  const required = new Set<string>(
    Array.isArray(effectiveSchema.required) ? effectiveSchema.required : [],
  );
  const propertyEntries = Object.entries(properties) as [string, JsonSchema][];
  const usingFallback = isEmptySchema(schema || undefined);

  const handleRawBlur = () => {
    try {
      const parsed = JSON.parse(rawText);
      if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
        setRawError('Root value must be a JSON object');
        return;
      }
      setRawError(null);
      emitChange(parsed);
    } catch (err) {
      setRawError(err instanceof Error ? err.message : 'Invalid JSON');
    }
  };

  return (
    <div className={`space-y-3 ${className}`}>
      <div className="flex items-center justify-between gap-2">
        <div className="min-w-0">
          <h3
            className={`text-sm font-semibold truncate ${
              darkMode ? 'text-white' : 'text-gray-900'
            }`}
          >
            {effectiveSchema.title || 'Input'}
          </h3>
          {usingFallback && (
            <p className={`text-[10px] ${darkMode ? 'text-amber-400' : 'text-amber-600'}`}>
              No custom schema — using default query field
            </p>
          )}
        </div>
        {showViewToggle && (
          <div
            className={`inline-flex rounded-lg p-0.5 text-xs ${
              darkMode ? 'bg-gray-700' : 'bg-gray-100'
            }`}
          >
            {(['form', 'raw'] as const).map((mode) => (
              <button
                key={mode}
                type="button"
                disabled={disabled}
                onClick={() => {
                  if (mode === 'raw') {
                    setRawText(JSON.stringify(formValue, null, 2));
                    setRawError(null);
                  } else {
                    handleRawBlur();
                  }
                  setViewMode(mode);
                }}
                className={`px-2 py-1 rounded-md transition-colors ${
                  viewMode === mode
                    ? darkMode
                      ? 'bg-gray-600 text-white'
                      : 'bg-white text-gray-900 shadow-sm'
                    : darkMode
                      ? 'text-gray-300 hover:text-white'
                      : 'text-gray-600 hover:text-gray-900'
                }`}
              >
                {mode === 'form' ? 'Form' : 'Raw JSON'}
              </button>
            ))}
          </div>
        )}
      </div>

      {effectiveSchema.description && (
        <p className={`text-xs ${darkMode ? 'text-gray-400' : 'text-gray-500'}`}>
          {effectiveSchema.description}
        </p>
      )}

      {viewMode === 'form' ? (
        <div
          className={`space-y-3 max-h-96 overflow-y-auto pr-1 ${
            disabled ? 'opacity-60 pointer-events-none' : ''
          }`}
        >
          {propertyEntries.length === 0 ? (
            <p className={`text-xs italic ${darkMode ? 'text-gray-500' : 'text-gray-400'}`}>
              Schema has no properties to render.
            </p>
          ) : (
            propertyEntries.map(([name, propSchema]) => (
              <SchemaField
                key={name}
                name={name}
                schema={propSchema}
                rootSchema={effectiveSchema}
                value={formValue[name]}
                required={required.has(name)}
                darkMode={darkMode}
                onChange={(fieldValue) =>
                  emitChange({ ...formValue, [name]: fieldValue })
                }
              />
            ))
          )}
        </div>
      ) : (
        <div>
          <textarea
            value={rawText}
            disabled={disabled}
            onChange={(e) => {
              setRawText(e.target.value);
              setRawError(null);
            }}
            onBlur={handleRawBlur}
            rows={12}
            className={`w-full px-2 py-2 text-xs font-mono border rounded ${
              darkMode
                ? 'bg-gray-700 border-gray-600 text-white'
                : 'bg-white border-gray-300 text-gray-900'
            } ${rawError ? 'border-red-500' : ''}`}
            spellCheck={false}
          />
          {rawError && (
            <p className="mt-1 text-[10px] text-red-500">{rawError}</p>
          )}
        </div>
      )}

      {submitLabel && onSubmit && (
        <button
          type="button"
          disabled={disabled}
          onClick={() => {
            if (viewMode === 'raw') {
              try {
                const parsed = JSON.parse(rawText);
                if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
                  setRawError(null);
                  emitChange(parsed);
                  onSubmit(parsed);
                  return;
                }
                setRawError('Root value must be a JSON object');
              } catch (err) {
                setRawError(err instanceof Error ? err.message : 'Invalid JSON');
              }
              return;
            }
            onSubmit(formValue);
          }}
          className={`w-full px-3 py-2 text-sm font-medium rounded-lg transition-colors ${
            darkMode
              ? 'bg-green-600 hover:bg-green-700 text-white disabled:bg-gray-600'
              : 'bg-green-600 hover:bg-green-700 text-white disabled:bg-gray-300'
          }`}
        >
          {submitLabel}
        </button>
      )}
    </div>
  );
};
