import React, { useState } from 'react';
import { isEmptySchema, summarizeSchemaProperties, type JsonSchema } from './schemaUtils';

export interface OutputSchemaSummaryProps {
  schema?: JsonSchema | null;
  darkMode?: boolean;
  className?: string;
}

/**
 * Compact read-only summary of an agent's output JSON Schema.
 * Helps debug expected response shape without cluttering the input form.
 */
export const OutputSchemaSummary: React.FC<OutputSchemaSummaryProps> = ({
  schema,
  darkMode = false,
  className = '',
}) => {
  const [expanded, setExpanded] = useState(false);
  const fields = summarizeSchemaProperties(schema || undefined);
  const empty = isEmptySchema(schema || undefined);

  return (
    <div
      className={`rounded-lg border ${
        darkMode ? 'border-gray-600 bg-gray-800/50' : 'border-gray-200 bg-gray-50'
      } ${className}`}
    >
      <button
        type="button"
        onClick={() => setExpanded((v) => !v)}
        className={`w-full flex items-center justify-between px-3 py-2 text-left ${
          darkMode ? 'hover:bg-gray-700/50' : 'hover:bg-gray-100'
        }`}
      >
        <div>
          <div
            className={`text-xs font-semibold ${
              darkMode ? 'text-gray-200' : 'text-gray-800'
            }`}
          >
            Expected output
          </div>
          <div className={`text-[10px] ${darkMode ? 'text-gray-500' : 'text-gray-400'}`}>
            {empty
              ? 'No output schema available'
              : `${fields.length} field${fields.length === 1 ? '' : 's'}`}
          </div>
        </div>
        <svg
          className={`w-4 h-4 transition-transform ${expanded ? 'rotate-90' : ''} ${
            darkMode ? 'text-gray-400' : 'text-gray-500'
          }`}
          fill="none"
          stroke="currentColor"
          viewBox="0 0 24 24"
        >
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={2}
            d="M9 5l7 7-7 7"
          />
        </svg>
      </button>

      {expanded && (
        <div
          className={`px-3 pb-3 border-t ${
            darkMode ? 'border-gray-700' : 'border-gray-200'
          }`}
        >
          {empty ? (
            <p
              className={`text-[10px] mt-2 italic ${
                darkMode ? 'text-gray-500' : 'text-gray-400'
              }`}
            >
              Agent did not expose an output schema.
            </p>
          ) : (
            <ul className="mt-2 space-y-1.5">
              {fields.map((field) => (
                <li key={field.name} className="text-xs">
                  <div className="flex items-center gap-2 flex-wrap">
                    <code
                      className={`px-1.5 py-0.5 rounded font-mono text-[10px] ${
                        darkMode
                          ? 'bg-gray-700 text-blue-300'
                          : 'bg-white text-blue-700 border border-gray-200'
                      }`}
                    >
                      {field.name}
                    </code>
                    <span
                      className={`text-[10px] ${
                        darkMode ? 'text-gray-400' : 'text-gray-500'
                      }`}
                    >
                      {field.type}
                    </span>
                    {field.required && (
                      <span className="text-[10px] text-red-500 font-medium">
                        required
                      </span>
                    )}
                  </div>
                  {field.description && (
                    <p
                      className={`mt-0.5 text-[10px] ${
                        darkMode ? 'text-gray-500' : 'text-gray-400'
                      }`}
                    >
                      {field.description}
                    </p>
                  )}
                </li>
              ))}
            </ul>
          )}

          {!empty && (
            <details className="mt-2">
              <summary
                className={`text-[10px] cursor-pointer ${
                  darkMode ? 'text-gray-400' : 'text-gray-500'
                }`}
              >
                View raw schema
              </summary>
              <pre
                className={`mt-1 p-2 rounded text-[10px] font-mono overflow-x-auto max-h-40 ${
                  darkMode
                    ? 'bg-gray-900 text-gray-300'
                    : 'bg-white text-gray-700 border border-gray-200'
                }`}
              >
                {JSON.stringify(schema, null, 2)}
              </pre>
            </details>
          )}
        </div>
      )}
    </div>
  );
};
