/**
 * Canvas ↔ pipeline-dict ↔ YAML serialization plus builder-side
 * structural validation for instant feedback.
 *
 * The canvas keeps loader-compatible raw step dicts, so the round-trip
 * is lossless: `draftFromPipelineDict(pipelineDictFromDraft(d))` returns
 * an equivalent draft, and the produced dict/YAML is exactly what the
 * backend loader accepts.
 */

import { dump as yamlDump, load as yamlLoad } from 'js-yaml';
import { v4 as uuidv4 } from 'uuid';

import { defaultChildren, defaultConfig } from './defaults';
import type {
  BuilderDraft,
  CanvasStep,
  PipelineMeta,
  StepConfig,
  StepKind,
  ValidationIssue,
} from './types';

// ---------------------------------------------------------------------------
// Draft construction
// ---------------------------------------------------------------------------

export function emptyMeta(): PipelineMeta {
  return {
    name: 'my_pipeline',
    description: '',
    version: '1.0.0',
    on_error: 'fail_fast',
    timeout: 300,
    strict_schema: false,
    input_schema: {},
    output_schema: {},
    defaults: {},
    metadata: {},
  };
}

export function emptyDraft(): BuilderDraft {
  return { meta: emptyMeta(), steps: [] };
}

export function makeStep(kind: StepKind, name: string): CanvasStep {
  return {
    id: uuidv4(),
    kind,
    name,
    config: defaultConfig(kind, name),
    children: defaultChildren(kind, name),
  };
}

/** Return a name not present in `existing` by appending _2, _3, … */
export function uniqueStepName(base: string, existing: string[]): string {
  const used = new Set(existing);
  let candidate = base;
  let counter = 2;
  while (used.has(candidate)) {
    candidate = `${base}_${counter}`;
    counter += 1;
  }
  return candidate;
}

// ---------------------------------------------------------------------------
// Kind detection / normalization
// ---------------------------------------------------------------------------

export function detectKind(dict: StepConfig): StepKind | null {
  if (dict && typeof dict === 'object') {
    if (dict.agent !== undefined) return 'agent';
    if (dict.plugin !== undefined) return 'plugin';
    if (dict.endpoint !== undefined) return 'endpoint';
    if (dict.ingestion !== undefined) return 'ingestion';
    if (dict.transform !== undefined) return 'transform';
    if (dict.parallel !== undefined) return 'parallel';
    if (dict.map !== undefined) return 'map';
    if (dict.loop !== undefined) return 'loop';
    if (dict.sub_pipeline !== undefined) return 'sub_pipeline';
  }
  return null;
}

/**
 * Normalize an input/output mapping to a plain `{field: expr}` dict.
 * Accepts both the YAML shape (`{field: expr}`) and the Pydantic dump
 * shape (`{mappings: {...}}`).
 */
export function normMapping(value: any): Record<string, any> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  if (
    typeof value.mappings === 'object' &&
    value.mappings !== null &&
    !Array.isArray(value.mappings)
  ) {
    return { ...value.mappings };
  }
  return { ...value };
}

function toCanvasStep(raw: StepConfig): CanvasStep {
  const kind = detectKind(raw) ?? 'agent';
  const name = typeof raw.name === 'string' && raw.name ? raw.name : kind;
  const config: StepConfig = { ...raw, name };

  let children: CanvasStep[] = [];
  if (kind === 'parallel' && Array.isArray(raw.parallel?.steps)) {
    children = raw.parallel.steps.map((child: any) => toCanvasStep(child));
  } else if (kind === 'loop' && raw.loop && typeof raw.loop === 'object') {
    const inner = raw.loop.step && typeof raw.loop.step === 'object' ? raw.loop.step : {};
    children = [toCanvasStep(inner)];
  }

  // Flatten Pydantic dump shapes into the YAML shapes the editor edits.
  for (const key of ['input', 'output']) {
    if (config[key] !== undefined) config[key] = normMapping(config[key]);
  }
  if (kind === 'map' && config.map && typeof config.map === 'object') {
    for (const key of ['input', 'output']) {
      if (config.map[key] !== undefined) config.map[key] = normMapping(config.map[key]);
    }
  }

  return { id: uuidv4(), kind, name, config, children };
}

export function draftFromPipelineDict(raw: any): BuilderDraft {
  const dict = raw && typeof raw === 'object' ? raw : {};
  const steps = Array.isArray(dict.steps) ? dict.steps : [];
  const meta: PipelineMeta = {
    name: typeof dict.name === 'string' && dict.name ? dict.name : 'my_pipeline',
    description: typeof dict.description === 'string' ? dict.description : '',
    version: typeof dict.version === 'string' ? dict.version : '1.0.0',
    on_error: ['fail_fast', 'continue', 'rollback'].includes(dict.on_error)
      ? dict.on_error
      : 'fail_fast',
    timeout: typeof dict.timeout === 'number' ? dict.timeout : 300,
    strict_schema: Boolean(dict.strict_schema),
    input_schema: dict.input_schema && typeof dict.input_schema === 'object' ? dict.input_schema : {},
    output_schema:
      dict.output_schema && typeof dict.output_schema === 'object' ? dict.output_schema : {},
    defaults: dict.defaults && typeof dict.defaults === 'object' ? dict.defaults : {},
    metadata: dict.metadata && typeof dict.metadata === 'object' ? dict.metadata : {},
  };
  return { meta, steps: steps.map((s: any) => toCanvasStep(s)) };
}

// ---------------------------------------------------------------------------
// Draft → loader-compatible dict / YAML
// ---------------------------------------------------------------------------

const TIMEOUT_DEFAULTS: Record<StepKind, number> = {
  agent: 30,
  plugin: 30,
  endpoint: 30,
  ingestion: 300,
  transform: 10,
  parallel: 60,
  map: 120,
  loop: 120,
  sub_pipeline: 120,
};

function mappingToDict(mapping: Record<string, any> | undefined): Record<string, any> | undefined {
  if (!mapping || Object.keys(mapping).length === 0) return undefined;
  return { ...mapping };
}

function retryToDict(retry: any): Record<string, any> | undefined {
  if (!retry || typeof retry !== 'object') return undefined;
  const out: Record<string, any> = {};
  if (retry.max_attempts !== undefined) out.max_attempts = retry.max_attempts;
  if (retry.backoff) out.backoff = retry.backoff;
  if (retry.base_delay !== undefined) out.base_delay = retry.base_delay;
  return Object.keys(out).length > 0 ? out : undefined;
}

/** Common optional fields for agent-like steps (agent/plugin/endpoint/…). */
function commonFields(step: CanvasStep, dict: StepConfig): StepConfig {
  const kind = step.kind;
  const c = step.config;
  const input = mappingToDict(c.input);
  if (input) dict.input = input;
  const output = mappingToDict(c.output);
  if (output) dict.output = output;
  if (typeof c.condition === 'string' && c.condition.trim()) dict.condition = c.condition;
  if (c.on_error && c.on_error !== 'fail') dict.on_error = c.on_error;
  if (c.fallback_agent) dict.fallback_agent = c.fallback_agent;
  if (Array.isArray(c.upstreams) && c.upstreams.length > 0) {
    dict.upstreams = [...c.upstreams];
  }
  const retry = retryToDict(c.retry);
  if (retry) dict.retry = retry;
  if (typeof c.timeout === 'number' && c.timeout !== TIMEOUT_DEFAULTS[kind]) {
    dict.timeout = c.timeout;
  }
  if (c.metadata && typeof c.metadata === 'object' && Object.keys(c.metadata).length > 0) {
    dict.metadata = { ...c.metadata };
  }
  if (typeof c.rollback === 'string' && c.rollback.trim()) dict.rollback = c.rollback;
  return dict;
}

export function stepToDict(step: CanvasStep): StepConfig {
  const kind = step.kind;
  const c = step.config;

  if (kind === 'transform') {
    const dict: StepConfig = { name: step.name, transform: c.transform ?? '' };
    if (typeof c.condition === 'string' && c.condition.trim()) dict.condition = c.condition;
    if (c.on_error && c.on_error !== 'fail') dict.on_error = c.on_error;
    if (typeof c.timeout === 'number' && c.timeout !== TIMEOUT_DEFAULTS.transform) {
      dict.timeout = c.timeout;
    }
    return dict;
  }

  if (kind === 'parallel') {
    const body: StepConfig = { steps: step.children.map((child) => stepToDict(child)) };
    if (c.parallel?.strategy && c.parallel.strategy !== 'all') {
      body.strategy = c.parallel.strategy;
    }
    if (typeof c.parallel?.max_concurrency === 'number' && c.parallel.max_concurrency !== 5) {
      body.max_concurrency = c.parallel.max_concurrency;
    }
    const dict: StepConfig = { name: step.name, parallel: body };
    if (c.on_error && c.on_error !== 'fail') dict.on_error = c.on_error;
    if (typeof c.timeout === 'number' && c.timeout !== TIMEOUT_DEFAULTS.parallel) {
      dict.timeout = c.timeout;
    }
    return dict;
  }

  if (kind === 'map') {
    const m = c.map && typeof c.map === 'object' ? c.map : {};
    const body: StepConfig = {
      agent: typeof m.agent === 'string' ? m.agent : '',
      items: typeof m.items === 'string' ? m.items : '',
    };
    if (m.item_key && m.item_key !== 'item') body.item_key = m.item_key;
    if (m.index_key && m.index_key !== 'index') body.index_key = m.index_key;
    const input = mappingToDict(m.input);
    if (input) body.input = input;
    const output = mappingToDict(m.output);
    if (output) body.output = output;
    if (typeof m.max_concurrency === 'number' && m.max_concurrency !== 4) {
      body.max_concurrency = m.max_concurrency;
    }
    if (m.strategy && m.strategy !== 'all') body.strategy = m.strategy;
    const retry = retryToDict(m.retry);
    if (retry) body.retry = retry;
    if (typeof m.item_timeout === 'number' && m.item_timeout !== 60) {
      body.item_timeout = m.item_timeout;
    }
    if (m.fallback_agent) body.fallback_agent = m.fallback_agent;
    const dict: StepConfig = { name: step.name, map: body };
    if (typeof c.condition === 'string' && c.condition.trim()) dict.condition = c.condition;
    if (c.on_error && c.on_error !== 'fail') dict.on_error = c.on_error;
    if (typeof c.timeout === 'number' && c.timeout !== TIMEOUT_DEFAULTS.map) {
      dict.timeout = c.timeout;
    }
    if (c.metadata && typeof c.metadata === 'object' && Object.keys(c.metadata).length > 0) {
      dict.metadata = { ...c.metadata };
    }
    if (typeof c.rollback === 'string' && c.rollback.trim()) dict.rollback = c.rollback;
    return dict;
  }

  if (kind === 'loop') {
    const inner = step.children[0];
    const body: StepConfig = { step: inner ? stepToDict(inner) : { name: '', agent: '' } };
    if (typeof c.loop?.max_iterations === 'number' && c.loop.max_iterations !== 10) {
      body.max_iterations = c.loop.max_iterations;
    }
    if (typeof c.loop?.until === 'string' && c.loop.until.trim()) body.until = c.loop.until;
    const dict: StepConfig = { name: step.name, loop: body };
    if (c.on_error && c.on_error !== 'fail') dict.on_error = c.on_error;
    if (typeof c.timeout === 'number' && c.timeout !== TIMEOUT_DEFAULTS.loop) {
      dict.timeout = c.timeout;
    }
    return dict;
  }

  if (kind === 'sub_pipeline') {
    const dict: StepConfig = { name: step.name, sub_pipeline: c.sub_pipeline ?? '' };
    return commonFields(step, dict);
  }

  // agent / plugin / endpoint / ingestion
  const discriminator: Record<string, string> = {
    agent: 'agent',
    plugin: 'plugin',
    endpoint: 'endpoint',
    ingestion: 'ingestion',
  };
  const dict: StepConfig = {
    name: step.name,
    [discriminator[kind]]: typeof c[discriminator[kind]] === 'string' ? c[discriminator[kind]] : '',
  };
  return commonFields(step, dict);
}

export function pipelineDictFromDraft(draft: BuilderDraft): Record<string, any> {
  const meta = draft.meta;
  const dict: Record<string, any> = {
    name: meta.name,
    steps: draft.steps.map((s) => stepToDict(s)),
  };
  if (meta.description) dict.description = meta.description;
  if (meta.version && meta.version !== '1.0.0') dict.version = meta.version;
  if (Object.keys(meta.input_schema).length > 0) dict.input_schema = meta.input_schema;
  if (Object.keys(meta.output_schema).length > 0) dict.output_schema = meta.output_schema;
  if (Object.keys(meta.defaults).length > 0) dict.defaults = meta.defaults;
  if (meta.on_error && meta.on_error !== 'fail_fast') dict.on_error = meta.on_error;
  if (meta.strict_schema) dict.strict_schema = true;
  if (meta.timeout !== 300) dict.timeout = meta.timeout;
  if (Object.keys(meta.metadata).length > 0) dict.metadata = meta.metadata;
  return dict;
}

export function yamlFromDraft(draft: BuilderDraft): string {
  return yamlDump(pipelineDictFromDraft(draft), { noRefs: true });
}

/** Parse YAML into a draft. Throws `Error` with a readable message. */
export function draftFromYaml(text: string): BuilderDraft {
  let parsed: any;
  try {
    parsed = yamlLoad(text);
  } catch (err: any) {
    throw new Error(`Invalid YAML: ${err?.message ?? String(err)}`);
  }
  if (!parsed || typeof parsed !== 'object' || !Array.isArray(parsed.steps)) {
    throw new Error('YAML must be a pipeline mapping with a "steps" list');
  }
  return draftFromPipelineDict(parsed);
}

// ---------------------------------------------------------------------------
// Immutable draft updates
// ---------------------------------------------------------------------------

export function setStepConfig(
  draft: BuilderDraft,
  id: string,
  childPath: string[],
  config: StepConfig,
): BuilderDraft {
  const steps = draft.steps.map((s) => {
    if (s.id !== id) return s;
    if (childPath.length === 0) {
      return { ...s, config: { ...config, name: s.name } };
    }
    const children = s.children.map((child) => {
      if (child.id !== childPath[0]) return child;
      return { ...child, config: { ...config, name: child.name } };
    });
    return { ...s, children };
  });
  return { ...draft, steps };
}

export function renameStep(
  draft: BuilderDraft,
  id: string,
  childPath: string[],
  name: string,
): BuilderDraft {
  const topNames = draft.steps.map((s) => s.name);
  const steps = draft.steps.map((s) => {
    if (s.id !== id) return s;
    if (childPath.length === 0) {
      const unique = uniqueStepName(name || s.name, topNames.filter((n) => n !== s.name));
      return { ...s, name: unique, config: { ...s.config, name: unique } };
    }
    const siblingNames = s.children.map((c) => c.name);
    const children = s.children.map((child) => {
      if (child.id !== childPath[0]) return child;
      const unique = uniqueStepName(name || child.name, siblingNames.filter((n) => n !== child.name));
      return { ...child, name: unique, config: { ...child.config, name: unique } };
    });
    return { ...s, children };
  });
  return { ...draft, steps };
}

export function setMeta(draft: BuilderDraft, meta: PipelineMeta): BuilderDraft {
  return { ...draft, meta };
}

export function addStep(draft: BuilderDraft, kind: StepKind): BuilderDraft {
  const name = uniqueStepName(
    kind === 'sub_pipeline' ? 'sub' : kind,
    draft.steps.map((s) => s.name),
  );
  return { ...draft, steps: [...draft.steps, makeStep(kind, name)] };
}

export function removeStep(draft: BuilderDraft, id: string): BuilderDraft {
  return { ...draft, steps: draft.steps.filter((s) => s.id !== id) };
}

export function reorderStep(
  draft: BuilderDraft,
  fromIndex: number,
  toIndex: number,
  containerId?: string,
): BuilderDraft {
  const reorder = (list: CanvasStep[]) => {
    const next = [...list];
    const [moved] = next.splice(fromIndex, 1);
    if (!moved) return list;
    const clamped = Math.max(0, Math.min(toIndex, next.length));
    next.splice(clamped, 0, moved);
    return next;
  };
  if (!containerId) {
    return { ...draft, steps: reorder(draft.steps) };
  }
  return {
    ...draft,
    steps: draft.steps.map((s) => (s.id === containerId ? { ...s, children: reorder(s.children) } : s)),
  };
}

export function addChild(draft: BuilderDraft, containerId: string): BuilderDraft {
  const steps = draft.steps.map((s) => {
    if (s.id !== containerId) return s;
    const kind: StepKind = 'agent';
    const name = uniqueStepName('child', s.children.map((c) => c.name));
    const child = makeStep(kind, name);
    return { ...s, children: [...s.children, child] };
  });
  return { ...draft, steps };
}

export function removeChild(
  draft: BuilderDraft,
  containerId: string,
  childId: string,
): BuilderDraft {
  const steps = draft.steps.map((s) => {
    if (s.id !== containerId) return s;
    const children = s.children.filter((c) => c.id !== childId);
    if (s.kind === 'loop' && children.length === 0) {
      return { ...s, children: [makeStep('agent', uniqueStepName('child', []))] };
    }
    return { ...s, children };
  });
  return { ...draft, steps };
}

// ---------------------------------------------------------------------------
// Structural validation (instant, client-side)
// ---------------------------------------------------------------------------

const INPUT_ROOTS = ['input', 'defaults', 'context', 'current', 'steps'];

interface MappingEntry {
  label: string;
  mapping: Record<string, any>;
  isInput: boolean;
  index: number;
}

function mappingEntries(step: CanvasStep, index: number): MappingEntry[] {
  const entries: MappingEntry[] = [];
  const push = (value: any, key: string, isInput: boolean) => {
    const mapping = normMapping(value);
    if (Object.keys(mapping).length > 0) {
      entries.push({ label: `Step '${step.name}' ${key} mapping`, mapping, isInput, index });
    }
  };
  push(step.config.input, 'input', true);
  push(step.config.output, 'output', false);
  if (step.kind === 'map' && step.config.map && typeof step.config.map === 'object') {
    push(step.config.map.input, 'input', true);
    push(step.config.map.output, 'output', false);
  }
  for (const child of step.children) {
    push(child.config.input, 'input', true);
    push(child.config.output, 'output', false);
  }
  return entries;
}

function checkMappingExpr(
  expr: any,
  label: string,
  isInput: boolean,
  index: number,
  topLevelNames: string[],
  issues: ValidationIssue[],
  stepName: string,
): void {
  if (typeof expr !== 'string' || !expr.startsWith('$')) return;
  const parts = expr.replace(/^\$\.?/, '').split('.').filter((p) => p.length > 0);

  if (!isInput) {
    if (parts.length > 0 && INPUT_ROOTS.includes(parts[0])) {
      issues.push({
        stepName,
        severity: 'warning',
        message: `${label}: output mapping '${expr}' starts with '${parts[0]}' — output mappings resolve against this step's own output, not the pipeline context`,
      });
    }
    return;
  }

  if (parts.length === 0) {
    issues.push({
      stepName,
      severity: 'warning',
      message: `${label}: expression '${expr}' resolves to nothing — use a path like '$.input.query'`,
    });
    return;
  }

  const root = parts[0];
  if (!INPUT_ROOTS.includes(root)) {
    issues.push({
      stepName,
      severity: 'error',
      message: `${label}: unknown mapping root '${root}' in '${expr}' (expected one of: ${INPUT_ROOTS.join(', ')})`,
    });
    return;
  }

  if (root === 'steps' && parts.length >= 2) {
    const ref = parts[1].split('[')[0];
    if (ref !== '*') {
      const refIndex = topLevelNames.indexOf(ref);
      if (refIndex === -1) {
        issues.push({
          stepName,
          severity: 'error',
          message: `${label}: '${expr}' references step '${ref}' which does not exist in the pipeline`,
        });
      } else if (refIndex >= index) {
        issues.push({
          stepName,
          severity: 'error',
          message: `${label}: '${expr}' references step '${ref}' which runs after this step — steps execute in order`,
        });
      }
    }
  }
}

function warnErrorPolicy(
  config: StepConfig,
  label: string,
  issues: ValidationIssue[],
  stepName: string,
): void {
  const policy = config.on_error;
  if (policy === 'skip') {
    issues.push({
      stepName,
      severity: 'warning',
      message: `${label} uses on_error=skip — failures will be silently ignored`,
    });
  } else if (policy === 'retry' && !config.retry) {
    issues.push({
      stepName,
      severity: 'warning',
      message: `${label} uses on_error=retry but has no retry config`,
    });
  } else if (policy === 'fallback' && !config.fallback_agent) {
    issues.push({
      stepName,
      severity: 'warning',
      message: `${label} uses on_error=fallback but has no fallback_agent`,
    });
  }
}

function stepIssues(
  step: CanvasStep,
  index: number,
  topLevelNames: string[],
  issues: ValidationIssue[],
): void {
  const label = `Step '${step.name}'`;
  const c = step.config;

  switch (step.kind) {
    case 'agent':
      if (!c.agent) issues.push({ stepName: step.name, severity: 'error', message: `${label} has no agent selected` });
      break;
    case 'plugin':
      if (!c.plugin) issues.push({ stepName: step.name, severity: 'error', message: `${label} has no plugin selected` });
      break;
    case 'endpoint':
      if (!c.endpoint) issues.push({ stepName: step.name, severity: 'error', message: `${label} has no endpoint selected` });
      break;
    case 'ingestion':
      if (!c.ingestion) issues.push({ stepName: step.name, severity: 'error', message: `${label} has no ingestor selected` });
      break;
    case 'sub_pipeline':
      if (!c.sub_pipeline) issues.push({ stepName: step.name, severity: 'error', message: `${label} has no pipeline selected` });
      break;
    case 'transform':
      if (!c.transform || !String(c.transform).trim()) {
        issues.push({ stepName: step.name, severity: 'error', message: `${label} has no transform code` });
      } else if (!String(c.transform).includes('return')) {
        issues.push({ stepName: step.name, severity: 'warning', message: `${label} transform code does not contain a 'return' — the step will produce no output` });
      }
      break;
    case 'parallel':
      if (step.children.length === 0) {
        issues.push({ stepName: step.name, severity: 'error', message: `${label} has no steps — add at least one agent step` });
      }
      for (const child of step.children) {
        if (!child.config.agent) {
          issues.push({
            stepName: child.name,
            severity: 'error',
            message: `Step '${child.name}' (inside parallel '${step.name}') has no agent selected`,
          });
        }
        warnErrorPolicy(child.config, `Step '${child.name}' (inside parallel '${step.name}')`, issues, child.name);
      }
      break;
    case 'map': {
      const m = c.map && typeof c.map === 'object' ? c.map : {};
      if (!m.agent) issues.push({ stepName: step.name, severity: 'error', message: `${label} has no agent selected` });
      if (!m.items) issues.push({ stepName: step.name, severity: 'error', message: `${label} has no items expression` });
      warnErrorPolicy(m, label, issues, step.name);
      break;
    }
    case 'loop':
      if (step.children.length !== 1) {
        issues.push({ stepName: step.name, severity: 'error', message: `${label} must contain exactly one agent step` });
      } else {
        const inner = step.children[0];
        if (!inner.config.agent) {
          issues.push({
            stepName: inner.name,
            severity: 'error',
            message: `Step '${inner.name}' (inside loop '${step.name}') has no agent selected`,
          });
        }
        warnErrorPolicy(inner.config, `Step '${inner.name}' (inside loop '${step.name}')`, issues, inner.name);
      }
      break;
  }

  if (step.kind !== 'parallel' && step.kind !== 'loop') {
    warnErrorPolicy(c, label, issues, step.name);
  }

  for (const entry of mappingEntries(step, index)) {
    for (const [key, expr] of Object.entries(entry.mapping)) {
      checkMappingExpr(
        expr,
        `${entry.label} '${key}'`,
        entry.isInput,
        entry.index,
        topLevelNames,
        issues,
        step.name,
      );
    }
  }
}

export function structuralIssues(draft: BuilderDraft): ValidationIssue[] {
  const issues: ValidationIssue[] = [];
  const meta = draft.meta;

  if (!meta.name || !meta.name.trim()) {
    issues.push({ severity: 'error', message: 'Pipeline name is required' });
  } else if (!/^[A-Za-z0-9][A-Za-z0-9_.-]*$/.test(meta.name)) {
    issues.push({
      severity: 'error',
      message: "Invalid pipeline name — use letters, digits, '_', '-', '.'",
    });
  }

  if (draft.steps.length === 0) {
    issues.push({ severity: 'error', message: 'Add at least one step to the pipeline' });
    return issues;
  }

  const topLevelNames = draft.steps.map((s) => s.name);
  const seen = new Set<string>();
  for (const name of topLevelNames) {
    if (!name || !name.trim()) {
      issues.push({ severity: 'error', message: 'Every step needs a name' });
    } else if (seen.has(name)) {
      issues.push({ severity: 'error', message: `Duplicate step name: '${name}'` });
    }
    seen.add(name);
  }

  draft.steps.forEach((step, index) => stepIssues(step, index, topLevelNames, issues));
  return issues;
}

// ---------------------------------------------------------------------------
// Server issue merging + per-step counts
// ---------------------------------------------------------------------------

const STEP_REF_RE = /Step '([^']+)'/g;

/** Merge server errors/warnings into builder issues, tagging step names. */
export function mergeServerIssues(
  issues: ValidationIssue[],
  serverErrors: string[],
  serverWarnings: string[],
): ValidationIssue[] {
  const merged = [...issues];
  for (const [messages, severity] of [
    [serverErrors, 'error'],
    [serverWarnings, 'warning'],
  ] as const) {
    for (const message of messages) {
      const match = STEP_REF_RE.exec(message);
      STEP_REF_RE.lastIndex = 0;
      merged.push({
        message,
        severity,
        stepName: match ? match[1] : undefined,
      });
    }
  }
  return merged;
}

export function issueCounts(issues: ValidationIssue[]): Record<string, { errors: number; warnings: number }> {
  const counts: Record<string, { errors: number; warnings: number }> = {};
  for (const issue of issues) {
    if (!issue.stepName) continue;
    const entry = counts[issue.stepName] ?? { errors: 0, warnings: 0 };
    if (issue.severity === 'error') entry.errors += 1;
    else entry.warnings += 1;
    counts[issue.stepName] = entry;
  }
  return counts;
}
