/**
 * Edits a `{field: expr}` mapping — one row per entry, with autocomplete
 * suggestions for the expression value. Rows are kept in local state with
 * stable ids (so typing never re-mounts the inputs) and committed to the
 * parent as a plain record on every change.
 */

import React, { useEffect, useRef, useState } from 'react';
import { Plus, X } from 'lucide-react';

import { TextInput } from './FieldControls';

export interface MappingEditorProps {
  /** 'input' or 'output' — used for the datalist id and caption. */
  label: string;
  mappings: Record<string, any>;
  /** Autocomplete options for the value column. */
  suggestions: string[];
  onChange: (next: Record<string, any>) => void;
  darkMode: boolean;
}

interface Row {
  id: number;
  key: string;
  value: string;
}

const rowsFromMappings = (mappings: Record<string, any>): Row[] =>
  Object.entries(mappings ?? {}).map(([key, value], index) => ({
    id: index,
    key,
    value: typeof value === 'string' ? value : value == null ? '' : String(value),
  }));

const recordFromRows = (rows: Row[]): Record<string, any> => {
  const record: Record<string, any> = {};
  for (const row of rows) record[row.key] = row.value;
  return record;
};

export const MappingEditor: React.FC<MappingEditorProps> = ({
  label,
  mappings,
  suggestions,
  onChange,
  darkMode,
}) => {
  const [rows, setRows] = useState<Row[]>(() => rowsFromMappings(mappings));
  const rowsRef = useRef(rows);
  rowsRef.current = rows;
  const nextId = useRef(rows.length);

  // Reflect external record changes (e.g. a reloaded pipeline) without
  // resetting rows the user is currently editing.
  useEffect(() => {
    const current = recordFromRows(rowsRef.current);
    if (JSON.stringify(current) === JSON.stringify(mappings ?? {})) return;
    setRows(rowsFromMappings(mappings ?? {}));
  }, [mappings]);

  const commit = (next: Row[]) => {
    setRows(next);
    onChange(recordFromRows(next));
  };

  const addRow = () => {
    nextId.current += 1;
    commit([...rows, { id: nextId.current, key: '', value: '' }]);
  };

  const editRow = (id: number, patch: Partial<Row>) => {
    commit(rows.map((row) => (row.id === id ? { ...row, ...patch } : row)));
  };

  const removeRow = (id: number) => {
    commit(rows.filter((row) => row.id !== id));
  };

  return (
    <div className="mb-3">
      <span
        className={`block text-xs font-medium mb-1 ${
          darkMode ? 'text-gray-400' : 'text-gray-600'
        }`}
      >
        {label === 'input' ? 'Input mappings' : 'Output mappings'}
      </span>

      <datalist id={`builder-mapping-${label}`}>
        {suggestions.map((s) => (
          <option key={s} value={s} />
        ))}
      </datalist>

      {rows.length === 0 && (
        <p className={`text-xs mb-2 ${darkMode ? 'text-gray-500' : 'text-gray-400'}`}>
          No mappings
        </p>
      )}

      {rows.map((row) => (
        <div key={row.id} className="flex items-center gap-1.5">
          <div className="flex-1">
            <TextInput
              value={row.key}
              placeholder="field"
              mono
              onChange={(v) => editRow(row.id, { key: v })}
              darkMode={darkMode}
            />
          </div>
          <div className="flex-[1.5]">
            <TextInput
              value={row.value}
              placeholder={label === 'input' ? '$.input...' : '$'}
              mono
              list={`builder-mapping-${label}`}
              onChange={(v) => editRow(row.id, { value: v })}
              darkMode={darkMode}
            />
          </div>
          <button
            onClick={() => removeRow(row.id)}
            title="Remove mapping"
            className={`p-1.5 rounded-lg transition-colors ${
              darkMode ? 'hover:bg-gray-600 text-gray-400' : 'hover:bg-gray-200 text-gray-500'
            }`}
          >
            <X size={14} />
          </button>
        </div>
      ))}

      <button
        onClick={addRow}
        className={`flex items-center gap-1 text-sm font-medium transition-colors ${
          darkMode ? 'text-blue-400 hover:text-blue-300' : 'text-blue-600 hover:text-blue-700'
        }`}
      >
        <Plus size={14} />
        Add mapping
      </button>
    </div>
  );
};
